Matching Ayahs
- = ଆଲିଫ୍, ଲାମ୍, ମୀମ୍। 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = ସେମାନେ ହିଁ ନିଜ ପ୍ରଭୁଙ୍କ ତରଫରୁ ସଠିକ୍ ପଥରେ ଅଛନ୍ତି, ଏବଂ ସେମାନେ ହିଁ ସଫଳଲାଭକାରୀ। 2:5; 31:5
- = ହେ ଇସ୍ରାଏଲର ସନ୍ତାନଗଣ! ମୋର ସେହି ଅନୁଗ୍ରହକୁ ସ୍ମରଣ କର ଯାହା ମୁଁ ତୁମ୍ଭମାନଙ୍କୁ ଦାନ କରିଥିଲି ଏବଂ ମୁଁ ତୁମ୍ଭମାନଙ୍କୁ ସମଗ୍ର ବିଶ୍ୱ (ଜାତି) ଉପରେ ଶ୍ରେଷ୍ଠତ୍ୱ ଦେଇଥିଲି। 2:47; 2:122
- = ସେହି ଏକ ସମୁଦାୟ ଥିଲା ଯାହା ଅତୀତରେ ଚାଲିଗଲା। ସେମାନେ ଯାହା ଅର୍ଜନ କରିଛନ୍ତି ତାହା ସେମାନଙ୍କ ପାଇଁ, ଏବଂ ତୁମ୍ଭେମାନେ ଯାହା ଅର୍ଜନ କରିଛ ତାହା ତୁମ୍ଭମାନଙ୍କ ପାଇଁ। ଏବଂ ସେମାନେ ଯାହା କରୁଥିଲେ ସେ ବିଷୟରେ ତୁମ୍ଭମାନଙ୍କୁ ପଚରାଯିବ ନାହିଁ। 2:134; 2:141
- = ସେମାନେ ତହିଁରେ ଅନନ୍ତକାଳ ରହିବେ। ସେମାନଙ୍କ ଶାସ୍ତି ହ୍ରାସ କରାଯିବ ନାହିଁ ଏବଂ ସେମାନଙ୍କୁ ଅବକାଶ ମଧ୍ୟ ଦିଆଯିବ ନାହିଁ। 2:162; 3:88
- = କିନ୍ତୁ ଯେଉଁମାନେ ଏହାପରେ ତୌବା କରନ୍ତି ଏବଂ ନିଜକୁ ସଂଶୋଧନ କରନ୍ତି। ନିଶ୍ଚୟ ଆଲ୍ଲାହ କ୍ଷମାଶୀଳ, ଅପାର ଦୟାଳୁ। 3:89; 24:5
- = ଏବଂ ଯେଉଁମାନେ କୁଫୁର କଲେ ଏବଂ ଆମର ଆୟାତସମୂହକୁ ମିଥ୍ୟା କହିଲେ – ସେମାନେ ହିଁ ଜାହନ୍ନମର ଅଧିବାସୀ। 5:10; 5:86
- = ଏବଂ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କ ନିଦର୍ଶନସମୂହ ମଧ୍ୟରୁ ଯେକୌଣସି ନିଦର୍ଶନ ସେମାନଙ୍କ ପାଖକୁ ଆସେ, ସେମାନେ ତାହାରୁ ମୁହଁ ଫେରାଇ ନିଅନ୍ତି। 6:4; 36:46
- = ଏବଂ ଆପଣଙ୍କ ପୂର୍ବରୁ ମଧ୍ୟ ରସୂଲମାନଙ୍କୁ ଉପହାସ କରାଯାଇଥିଲା, କିନ୍ତୁ ଯେଉଁମାନେ ଉପହାସ କରୁଥିଲେ ସେମାନଙ୍କୁ ସେହି ବିଷୟ ଘେରି ରଖିଲା ଯାହାର ସେମାନେ ଉପହାସ କରୁଥିଲେ। 6:10; 21:41
- = କୁହନ୍ତୁ: "ଯଦି ମୁଁ ମୋର ପ୍ରଭୁଙ୍କ ଅବମାନନା କରେ, ତେବେ ମୁଁ ମହାଦିନର ଶାସ୍ତିକୁ ଭୟ କରେ।" 6:15; 39:13
- = ତେଣୁ ଭୂମିକମ୍ପ ସେମାନଙ୍କୁ ଧରି ପକାଇଲା, ଫଳରେ ସେମାନେ ନିଜ ଘରେ ଅଧୋମୁଖୀ ହୋଇ ପଡ଼ି ରହିଲେ। 7:78; 7:91
- = ତେଣୁ ସେ (ମୂସା) ନିଜର ଲାଠି ଫୋପାଡ଼ିଲେ, ଏବଂ ତତକ୍ଷଣାତ୍ ସେହି ଏକ ସ୍ପଷ୍ଟ ସର୍ପ ହୋଇଗଲା। 7:107; 26:32
- = ଏବଂ ସେ ନିଜର ହାତ ବାହାର କଲେ, ଫଳରେ ସେହି ଦର୍ଶକମାନଙ୍କ ପାଇଁ ଉଜ୍ଜ୍ୱଳ ଧଳା ହୋଇଗଲା। 7:108; 26:33
- = ସେମାନେ କହିଲେ: "ଆମେ ସମଗ୍ର ବିଶ୍ୱର ପ୍ରଭୁଙ୍କ ଉପରେ ଈମାନ ଆଣିଲୁ।" 7:121; 26:47
- = ମୂସା ଏବଂ ହାରୁନଙ୍କ ପ୍ରଭୁ। 7:122; 26:48
- = ଏବଂ ମୁଁ ସେମାନଙ୍କୁ ଅବକାଶ ଦେବି। ନିଶ୍ଚୟ ମୋର ଯୋଜନା ସୁଦୃଢ଼। 7:183; 68:45
- = ସେ ହିଁ ନିଜ ରସୂଲଙ୍କୁ ସଠିକ୍ ପଥ ଏବଂ ସତ୍ୟ ଧର୍ମ ସହିତ ପଠାଇଛନ୍ତି, ଯାହାଫଳରେ ସେ ଏହାକୁ ସମସ୍ତ ଧର୍ମ ଉପରେ ପ୍ରଭାବଶାଳୀ କରନ୍ତୁ, ଯଦିଓ ମୁଶ୍ରିକମାନେ ଏହାକୁ ଘୃଣା କରନ୍ତି। 9:33; 61:9
- = ହେ ନବୀ! କାଫିର ଏବଂ ମୁନାଫିକମାନଙ୍କ ସହିତ ଯୁଦ୍ଧ କର ଏବଂ ସେମାନଙ୍କ ପ୍ରତି କଠୋର ହୁଅ। ସେମାନଙ୍କ ଆଶ୍ରୟସ୍ଥଳ ଜାହନ୍ନମ, ଏବଂ ତାହା କେତେ ନିକୃଷ୍ଟ ପ୍ରତ୍ୟାବର୍ତ୍ତନସ୍ଥଳ! 9:73; 66:9
- = ଏବଂ ସେମାନେ କହନ୍ତି: "ଯଦି ତୁମ୍ଭେମାନେ ସତ୍ୟବାଦୀ, ତେବେ ଏହି ପ୍ରତିଶ୍ରୁତି କେବେ?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = ଏବଂ ଆମେ ମୂସାଙ୍କୁ ଆମର ନିଦର୍ଶନ ଏବଂ ସ୍ପଷ୍ଟ କର୍ତ୍ତୃତ୍ୱ ସହିତ ପଠାଇଥିଲୁ। 11:96; 40:23
- = ଏବଂ ଆମେ ମୂସାଙ୍କୁ କିତାବ ଦେଇଥିଲୁ, କିନ୍ତୁ ତହିଁରେ ମତଭେଦ ସୃଷ୍ଟି ହୋଇଥିଲା। ଏବଂ ଯଦି ଆପଣଙ୍କ ପ୍ରଭୁଙ୍କ ତରଫରୁ ଏକ ପୂର୍ବବର୍ତ୍ତୀ ବାକ୍ୟ ନଥାଆନ୍ତା, ତେବେ ସେମାନଙ୍କ ମଧ୍ୟରେ ଚୂଡ଼ାନ୍ତ ନିର୍ଣ୍ଣୟ ହୋଇସାରିଥାଆନ୍ତା। ଏବଂ ନିଶ୍ଚୟ ସେମାନେ ଏହି ବିଷୟରେ ସନ୍ଦେହରେ ଅଛନ୍ତି। 11:110; 41:45
- = ଏହା ଆଲ୍ଲାହଙ୍କ ପାଇଁ କଠିନ ନୁହେଁ। 14:20; 35:17
- = "ଯେତେବେଳେ ମୁଁ ତାକୁ ସୁସଂପନ୍ନ କରିବି ଏବଂ ମୋର ସୃଷ୍ଟ ଆତ୍ମାରୁ ତହିଁରେ ଫୁଙ୍କ ଦେବି, ସେତେବେଳେ ତୁମ୍ଭେମାନେ ତାଙ୍କ ପାଇଁ ସାଷ୍ଟାଙ୍ଗରେ ପଡ଼ିଯାଅ।" 15:29; 38:72
- = ତେଣୁ ସମସ୍ତ ଫିରିଶ୍ତାମାନେ ସାଷ୍ଟାଙ୍ଗ କଲେ। 15:30; 38:73
- = (ଆଲ୍ଲାହ) କହିଲେ: "ତେବେ ତୁମେ ତହିଁରୁ ବାହାରି ଯାଅ, କାରଣ ନିଶ୍ଚୟ ତୁମେ ତିରସ୍କୃତ।" 15:34; 38:77
- = (ଇବ୍ଲୀସ) କହିଲା: "ହେ ମୋର ପ୍ରଭୁ! ତେବେ ମୋତେ ସେହି ଦିନ ପର୍ୟ୍ୟନ୍ତ ଅବକାଶ ଦିଅ ଯେବେ ସେମାନେ ପୁନରୁତ୍ଥିତ ହେବେ।" 15:36; 38:79
- = (ଆଲ୍ଲାହ) କହିଲେ: "ତେବେ ନିଶ୍ଚୟ ତୁମେ ଅବକାଶପ୍ରାପ୍ତମାନଙ୍କ ମଧ୍ୟରୁ।" 15:37; 38:80
- = ନିର୍ଦ୍ଦିଷ୍ଟ ସମୟର ଦିନ ପର୍ୟ୍ୟନ୍ତ।" 15:38; 38:81
- = ସେମାନଙ୍କ ମଧ୍ୟରୁ ତୁମ୍ଭର ନିର୍ବାଚିତ ଦାସମାନେ ବ୍ୟତୀତ। 15:40; 38:83
- = ନିଶ୍ଚୟ ମୁତ୍ତାକୀ (ସଚେତନ) ମାନେ ବଗିଚା ଏବଂ ଝରଣାସମୂହରେ ରହିବେ। 15:45; 51:15
- = ସେ (ଇବ୍ରାହୀମ) କହିଲେ: "ତେବେ ତୁମ୍ଭମାନଙ୍କର କାର୍ଯ୍ୟ କ'ଣ, ହେ ରସୂଲମାନେ?" 15:57; 51:31
- = ସେମାନେ କହିଲେ: "ଆମେ ଅପରାଧୀ ସମୁଦାୟ ପାଖକୁ ପଠାଯାଇଛୁ।" 15:58; 51:32
- = ଯେଉଁମାନେ ଈମାନ ଆଣନ୍ତି ଏବଂ ନିଜର ଈମାନକୁ ଜୁଲୁମ ସହିତ ମିଶ୍ରଣ କରନ୍ତି ନାହିଁ – ସେମାନଙ୍କ ପାଇଁ ସୁରକ୍ଷା ଅଛି, ଏବଂ ସେମାନେ ହିଁ ସଠିକ୍ ପଥରେ ଅଛନ୍ତି। 16:42; 29:59
- = ଯାହାଫଳରେ ସେମାନେ ଆମେ ଦେଇଥିବା ବିଷୟର ଇନ୍କାର କରନ୍ତି। ତେଣୁ ତୁମ୍ଭେମାନେ ଉପଭୋଗ କର, କାରଣ ଶୀଘ୍ର ଜାଣିପାରିବ। 16:55; 30:34
- = ତା'ପରେ ସେ (ଜୁଲକର୍ନୈନ) ଏକ ପଥ ଗ୍ରହଣ କଲେ। 18:89; 18:92
- = ଫିରଔନ ପାଖକୁ ଯାଅ, କାରଣ ସେ ନିଶ୍ଚୟ ବିଦ୍ରୋହ କରିଛି। 20:24; 79:17
- = ଏବଂ ଯେଉଁମାନେ ନିଜର ଗୁପ୍ତାଙ୍ଗର ରକ୍ଷା କରନ୍ତି। 23:5; 70:29
- = ନିଜର ସ୍ତ୍ରୀ କିମ୍ବା ନିଜର ଡାହାଣ ହାତର ଅଧିକାରୀ (ଦାସୀ) ବ୍ୟତୀତ – କାରଣ ସେମାନେ ନିନ୍ଦନୀୟ ନୁହଁନ୍ତି। 23:6; 70:30
- = କିନ୍ତୁ ଯେଉଁମାନେ ଏହା ବ୍ୟତୀତ ବିଚାରନ୍ତି, ସେମାନେ ହିଁ ସୀମା ଲଙ୍ଘନକାରୀ। 23:7; 70:31
- = ଏବଂ ଯେଉଁମାନେ ନିଜର ଆମାନତ ଏବଂ ପ୍ରତିଜ୍ଞାସମୂହର ପାଳନ କରନ୍ତି। 23:8; 70:32
- = (ନୂହ) କହିଲେ: "ହେ ମୋର ପ୍ରଭୁ! ସେମାନେ ମୋତେ ମିଥ୍ୟା କହିଛନ୍ତି, ତେଣୁ ମୋର ସହାୟତା କର।" 23:26; 23:39
- = ତା, ସୀନ, ମୀମ। 26:1; 28:1
- = ଏହି ଗୁଡ଼ିକ ସ୍ପଷ୍ଟ କିତାବର ଆୟାତ। 26:2; 28:2
- = ନିଶ୍ଚୟ ଏହାରେ ଏକ ନିଦର୍ଶନ ଅଛି, କିନ୍ତୁ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଅଧିକାଂଶ ଈମାନ ଆଣିଲେ ନାହିଁ। 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = ଏବଂ ନିଶ୍ଚୟ ଆପଣଙ୍କ ପ୍ରଭୁ – ସେ ହିଁ ପରାକ୍ରମଶାଳୀ, ଅପାର ଦୟାଳୁ। 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = ଏବଂ ଆମେ ଅନ୍ୟମାନଙ୍କୁ ବୁଡ଼ାଇ ଦେଲୁ। 26:66; 37:82
- = ନିଶ୍ଚୟ ମୁଁ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ବିଶ୍ୱସ୍ତ ରସୂଲ। 26:107; 26:125; 26:143; 26:162; 26:178
- = ତେଣୁ ତୁମ୍ଭେମାନେ ଆଲ୍ଲାହଙ୍କୁ ଭୟ କର ଏବଂ ମୋର ଆଜ୍ଞା ପାଳନ କର। 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = ଏବଂ ମୁଁ ଏଥିପାଇଁ ତୁମ୍ଭମାନଙ୍କଠାରୁ କୌଣସି ପ୍ରତିଫଳ ମାଗୁନାହିଁ; ମୋର ପ୍ରତିଫଳ ତ ସମଗ୍ର ବିଶ୍ୱର ପ୍ରଭୁଙ୍କ ପାଖରେ। 26:109; 26:127; 26:145; 26:164; 26:180
- = ବଗିଚା ଏବଂ ଝରଣାସମୂହରେ। 26:147; 44:52
- = ସେମାନେ କହିଲେ: "ତୁମେ ତ ଯାଦୁର ପ୍ରଭାବିତମାନଙ୍କ ମଧ୍ୟରୁ।" 26:153; 26:185
- = ତାଙ୍କର ସ୍ତ୍ରୀ ବ୍ୟତୀତ – ଆମେ ନିର୍ଦ୍ଧାରଣ କରିଥିଲୁ ଯେ ସେ ପଛରେ ରହିଯାଉଥିବାମାନଙ୍କ ମଧ୍ୟରେ। 26:171; 37:135
- = ତା'ପରେ ଆମେ ଅନ୍ୟମାନଙ୍କୁ ଧ୍ୱଂସ କରିଦେଲୁ। 26:172; 37:136
- = ଏବଂ ଆମେ ସେମାନଙ୍କ ଉପରେ (ପଥରର) ବର୍ଷା କଲୁ, ଏବଂ ସତର୍କ କରାଯାଇଥିବା ଲୋକଙ୍କ ଉପରେ ବର୍ଷା କେତେ ନିକୃଷ୍ଟ ଥିଲା! 26:173; 27:58
- = ତେଣୁ ସେମାନେ ଶାସ୍ତିକୁ ଶୀଘ୍ର ଚାହୁଁଛନ୍ତି? 26:204; 37:176
- = ଯେଉଁମାନେ ସଲାତ କାୟମ କରନ୍ତି, ଜକାତ ଦିଅନ୍ତି, ଏବଂ ସେମାନେ ପରକାଳ ବିଷୟରେ ଦୃଢ଼ ବିଶ୍ୱାସ ରଖନ୍ତି। 27:3; 31:4
- = ଏବଂ (ସ୍ମରଣ କରନ୍ତୁ) ସେହି ଦିନକୁ ଯେତେବେଳେ ସେ ସେମାନଙ୍କୁ ଡାକିବେ ଏବଂ କହିବେ: "ମୋର ସେହି 'ଭାଗୀଦାର'ମାନେ କେଉଁଠାରେ, ଯେଉଁମାନଙ୍କ ବିଷୟରେ ତୁମ୍ଭେମାନେ ଦାବୀ କରୁଥିଲ?" 28:62; 28:74
- = ଏବଂ ଆମର ପୂର୍ବପୁରୁଷମାନେ? 37:17; 56:48
- = ଏବଂ ସେମାନେ ପରସ୍ପର ନିକଟକୁ ଯାଇ ପରସ୍ପରକୁ ପଚାରିବେ। 37:27; 52:25
- = କିନ୍ତୁ (ସେମାନେ) ଆଲ୍ଲାହଙ୍କ ନିର୍ବାଚିତ ଦାସ। 37:40; 37:74; 37:128; 37:160
- = ସୁଖ-ଶାନ୍ତିର ବଗିଚାସମୂହରେ। 37:43; 56:12
- = ଏବଂ ଆମେ ତାଙ୍କ ପାଇଁ ପରବର୍ତ୍ତୀମାନଙ୍କ ମଧ୍ୟରେ (ସୁନାମ) ରଖିଲୁ: 37:78; 37:108; 37:129
- = ନିଶ୍ଚୟ ଆମେ ସତ୍କର୍ମୀମାନଙ୍କୁ ଏହିପରି ପ୍ରତିଫଳ ଦେଇଥାଉ। 37:80; 37:121; 37:131; 77:44
- = ନିଶ୍ଚୟ ସେ ଆମର ଈମାନଦାର ଦାସମାନଙ୍କ ମଧ୍ୟରୁ ଥିଲେ। 37:81; 37:111; 37:132
- = ତୁମ୍ଭମାନଙ୍କର କ'ଣ ହୋଇଛି? କିପରି ନିର୍ଣ୍ଣୟ କରୁଛ? 37:154; 68:36
