- ସେମାନଙ୍କର ସମ୍ପତ୍ତି ଏବଂ ସେମାନଙ୍କର ସନ୍ତାନସନ୍ତତି ଅଲ୍ଲାହଙ୍କ ନିକଟରେ ସେମାନଙ୍କର କୌଣସି କାମରେ ଆସିବ ନାହିଁ, ଏବଂ ସେମାନେ ହିଁ। (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- ସ୍ୱର୍ଗ ବଗିଚାଗୁଡ଼ିକ ଯାହାର ତଳ ଦେଇ ନଦୀମାନ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ସଦାକାଳ ରହିବେ, ଏବଂ ତାହା ହିଁ ମହାନ ସଫଳତା। (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- ସେମାନଙ୍କ ପୂର୍ବବର୍ତ୍ତୀମାନଙ୍କର, ନୂହ, ଆଦ ଏବଂ ସମୂଦ ଜାତିଙ୍କର ସମ୍ବାଦ କ'ଣ ସେମାନଙ୍କ ନିକଟରେ ପହଞ୍ଚି ନାହିଁ? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- ଅଲ୍ଲାହଙ୍କ ପଥରେ ମୋର ସହାୟକମାନେ କିଏ? ଶିଷ୍ୟମାନେ କହିଲେ: "ଆମେ ଅଲ୍ଲାହଙ୍କ ସହାୟକ, ଆମେ ଈମାନ ଆଣିଛୁ।" (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- ତୁମ୍ଭର ପ୍ରଭୁ ସେ ଭଲ ଭାବରେ ଜାଣନ୍ତି ଯେ ତାଙ୍କ ପଥରୁ କିଏ ବିଚ୍ୟୁତ ହୋଇଛି, ଏବଂ ସେ ଭଲ ଭାବରେ ଜାଣନ୍ତି ସଠିକ୍ ପଥପ୍ରାପ୍ତମାନଙ୍କୁ। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- ଏହା କାରଣ ଅଲ୍ଲାହ ହିଁ ସତ୍ୟ, ଏବଂ ସେମାନେ ତାଙ୍କୁ ଛାଡ଼ି ଯାହାକୁ ଡାକନ୍ତି ତାହା ଅସତ୍ୟ। (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- ଆଉ ଯେ ଅଲ୍ଲାହ ଓ ତାଙ୍କ ରସୂଲଙ୍କ ଆଜ୍ଞାପାଳନ କରେ, ଅଲ୍ଲାହ ତାଙ୍କୁ ସେହି ସ୍ୱର୍ଗ ବଗିଚାଗୁଡ଼ିକରେ ପ୍ରବେଶ କରାଇବେ ଯାହାର ତଳ ଦେଇ ନଦୀମାନ ପ୍ରବାହିତ। (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- ସେ ତୁମ୍ଭମାନଙ୍କୁ କେବଳ ମୃତ ପ୍ରାଣୀ, ରକ୍ତ, ଘୁଷୁରି ମାଂସ ଏବଂ ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ ଅନ୍ୟ କାହାର ନାମରେ ଯାହା ବଳି ଦିଆଯାଏ ତାହା ହରାମ କରିଛନ୍ତି। (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ଯେ ତୁମେମାନେ ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ ଅନ୍ୟ କାହାର ଉପାସନା କର ନାହିଁ; ନିଶ୍ଚୟ ମୁଁ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ମହାଦିନର ଶାସ୍ତିକୁ ଭୟ କରେ। (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- ଏହା ଗୁପ୍ତ ସମ୍ବାଦଗୁଡ଼ିକ ମଧ୍ୟରୁ ଅଟେ ଯାହା ଆମେ ତୁମ୍ଭକୁ ବହି କରୁଅଛୁ; ସେମାନେ ଯେତେବେଳେ ନିଷ୍ପତ୍ତି ନେଉଥିଲେ, ତୁମ୍ଭେ ସେମାନଙ୍କ ନିକଟରେ ଥିଲ ନାହିଁ। (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- ତୁମ୍ଭେମାନେ କ'ଣ ଆଶ୍ଚର୍ଯ୍ୟ ହେଉଛ ଯେ ତୁମ୍ଭମାନଙ୍କ ପ୍ରଭୁଙ୍କ ତରଫରୁ ତୁମ୍ଭମାନଙ୍କ ମଧ୍ୟରୁ ଜଣେ ବ୍ୟକ୍ତିଙ୍କ ମାଧ୍ୟମରେ ତୁମ୍ଭମାନଙ୍କ ନିକଟକୁ ଉପଦେଶ ଆସିଲା, ଯାହା ଦ୍ୱାରା ସେ ତୁମ୍ଭମାନଙ୍କୁ ସତର୍କ କରାଇବ? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- କୁହ: "ନିଶ୍ଚୟ ମୋତେ ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ ତୁମ୍ଭେମାନେ ଯାହାକୁ ଡାକ ତାହାର ଉପାସନା କରିବାକୁ ମନା କରାଯାଇଛି।" (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- ନିଜ ସ୍ତ୍ରୀ କିମ୍ବା ନିଜ ଡାହାଣ ହାତର ଅଧିକାରଭୁକ୍ତ ଦାସୀମାନଙ୍କ ବ୍ୟତୀତ, କାରଣ ସେମାନେ ଦୋଷୀ ନୁହଁନ୍ତି। (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- କାରଣ ଅଲ୍ଲାହ ରାତ୍ରିକୁ ଦିବସରେ ଏବଂ ଦିବସକୁ ରାତ୍ରିରେ ପ୍ରବେଶ କରାନ୍ତି। (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- ଅଗ୍ନି, ଏବଂ ସେ ନିଜ ପରିବାରକୁ କହିଲା: "ଅପେକ୍ଷା କର, ମୁଁ ଅଗ୍ନି ଦେଖିଲି, ହୁଏତ ମୁଁ ତାହା ମଧ୍ୟରୁ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ କିଛି ଆଣି ପାରେ।" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- ସେ କହିଲା: "ମୁଁ ତାଠାରୁ ଶ୍ରେଷ୍ଠ; ତୁମ୍ଭେ ମୋତେ ଅଗ୍ନିରୁ ସୃଷ୍ଟି କରିଛ, ଏବଂ ତାଙ୍କୁ ମାଟିରୁ ସୃଷ୍ଟି କରିଛ।" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- ଏବଂ ଯେତେବେଳେ ସେମାନଙ୍କୁ କୁହାଯାଏ: "ଅଲ୍ଲାହ ଯାହା ଅବତୀର୍ଣ୍ଣ କରିଛନ୍ତି ଓ ରସୂଲଙ୍କ ଆଡକୁ ଆସ।" (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- ଏବଂ ତୁମ୍ଭେ ସେମାନଙ୍କ ପାଇଁ ଦୁଃଖ କର ନାହିଁ, ଏବଂ ସେମାନଙ୍କ ଷଡଯନ୍ତ୍ର ଯୋଗୁଁ ସଙ୍କୁଚିତ ହୁଅ ନାହିଁ। (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- ଏବଂ ଯଦି ଅଲ୍ଲାହ ତୁମ୍ଭକୁ କୌଣସି କ୍ଷତି ପହଞ୍ଚାନ୍ତି, ତେବେ ତାଙ୍କ ବ୍ୟତୀତ ଆଉ କେହି ତାହା ଦୂର କରିପାରିବ ନାହିଁ, ଏବଂ ଯଦି। (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- ସେମାନଙ୍କ ପୂର୍ବରୁ ଅନେକ ପୁରୁଷ ଯେଉଁମାନେ ନିଜ ଘରେ ବିଚରଣ କରୁଥିଲେ; ନିଶ୍ଚୟ ଏଥିରେ ନିଦର୍ଶନ ଅଛି। (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- ଏବଂ ଆମେ ସେମାନଙ୍କ ହୃଦୟ ଉପରେ ପରଦା ଦେଲୁ, ଯାହା ଦ୍ୱାରା ସେମାନେ ତାହା ବୁଝିପାରିବେ ନାହିଁ, ଏବଂ ସେମାନଙ୍କ କାନରେ ବଧିରତା, ଏବଂ ଯଦି। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- ସେମାନଙ୍କ ରସୂଲମାନେ ସ୍ପଷ୍ଟ ପ୍ରମାଣ ସହିତ ସେମାନଙ୍କ ନିକଟକୁ ଆସିଲେ, କିନ୍ତୁ ଅଲ୍ଲାହ ସେମାନଙ୍କ ଉପରେ ଅତ୍ୟାଚାର କରୁଥିଲେ ନାହିଁ, ବରଂ ସେମାନେ ନିଜେ ନିଜ ଉପରେ ଅତ୍ୟାଚାର କରୁଥିଲେ। (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- ଏବଂ ପୃଥିବୀରେ, ଏବଂ ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ ତୁମ୍ଭମାନଙ୍କର କୌଣସି ଅଭିଭାବକ କିମ୍ବା ସହାୟକ ନାହିଁ। (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ତା'ପରେ ତୁମ୍ଭମାନଙ୍କୁ ଗୁପ୍ତ ଓ ପ୍ରକାଶ୍ୟର ଜ୍ଞାତାଙ୍କ ନିକଟକୁ ଫେରାଇ ନିଆଯିବ, ଏବଂ ସେ ତୁମ୍ଭମାନଙ୍କୁ ଯାହା କରୁଥିଲ ତାହା ଜଣାଇବେ। (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ରାତ୍ରି, ଯାହା ଦ୍ୱାରା ତୁମେମାନେ ବିଶ୍ରାମ ନେବ, ଏବଂ ଦିବସ, ଯାହା ଦ୍ୱାରା ତୁମେମାନେ ଦେଖିବ; ନିଶ୍ଚୟ ଏଥିରେ ଚିନ୍ତାକାରୀ ଲୋକଙ୍କ ପାଇଁ ନିଦର୍ଶନ ଅଛି। (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
