- ନିଶ୍ଚୟ ମୁଁ ସେମାନଙ୍କର ପାପଗୁଡ଼ିକୁ କ୍ଷମା କରିବି ଏବଂ ସେମାନଙ୍କୁ ସେହି ସ୍ୱର୍ଗ ବଗିଚାଗୁଡ଼ିକରେ ପ୍ରବେଶ କରାଇବି ଯାହାର ତଳ ଦେଇ ନଦୀମାନ ପ୍ରବାହିତ। (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- ଆମେ ସେମାନଙ୍କୁ ସେହି ସ୍ୱର୍ଗ ବଗିଚାଗୁଡ଼ିକରେ ପ୍ରବେଶ କରାଇବୁ ଯାହାର ତଳ ଦେଇ ନଦୀମାନ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ସଦାକାଳ ରହିବେ। (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- ତୁମ୍ଭର ପ୍ରଭୁ ସେ ଭଲ ଭାବରେ ଜାଣନ୍ତି ଯେ ତାଙ୍କ ପଥରୁ କିଏ ବିଚ୍ୟୁତ ହୋଇଛି, ଏବଂ ସେ ଭଲ ଭାବରେ ଜାଣନ୍ତି। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
