- ତୁମ୍ଭମାନଙ୍କ ପୂର୍ବବର୍ତ୍ତୀ ଉମ୍ମତମାନଙ୍କ ମଧ୍ୟରେ, ଜିନ୍ ଓ ମନୁଷ୍ୟମାନଙ୍କ ମଧ୍ୟରେ। (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- ଅଲ୍ଲାହଙ୍କ ଉପାସନା କର, ତାଙ୍କ ବ୍ୟତୀତ ତୁମ୍ଭର କୌଣସି ଉପାସ୍ୟ ନାହିଁ, ତୁମେମାନେ କ'ଣ ଭୟ କରୁନାହଁ? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
