- ସେ କ୍ୟାମତ ଦିନ ସେମାନଙ୍କ ମଧ୍ୟରେ ଯେଉଁ ବିଷୟରେ ସେମାନେ ମତଭେଦ କରୁଥିଲେ, ତାହାର ଫଇସଲା କରିବେ। (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- ସେ କହିଲା: "ହେ ମୋର ସମ୍ପ୍ରଦାୟ! ତୁମ୍ଭେମାନେ କ'ଣ କୁହ, ଯଦି ମୁଁ ମୋର ପ୍ରଭୁଙ୍କ ତରଫରୁ ସ୍ପଷ୍ଟ ପ୍ରମାଣ ଉପରେ ଅଛି?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
