- ସେମାନଙ୍କ ପାଇଁ ଦୁନିଆରେ ଅପମାନ ଏବଂ ଆଖିରତରେ ମହାନ ଶାସ୍ତି ଅଛି। (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- ଆକାଶମଣ୍ଡଳରେ ଓ ପୃଥିବୀରେ ଯାହା ଅଛି, ଏବଂ ଅଲ୍ଲାହ ଅଭିଭାବକ ରୂପେ ଯଥେଷ୍ଟ। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- କିନ୍ତୁ ଯେଉଁମାନେ ଈମାନ ଆଣିଲେ ଏବଂ ସତ୍କର୍ମ କଲେ; ସେମାନଙ୍କ ପାଇଁ ଅବ୍ୟାହତ ପୁରସ୍କାର ଅଛି। (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- ଯେ ତୁମ୍ଭେ ମୋ' ସହିତ ସେହି ଜିନିଷକୁ ଭାଗୀଦାର କର ଯାହାର ତୁମ୍ଭର କୌଣସି ଜ୍ଞାନ ନାହିଁ; ସେମାନଙ୍କ ଆଜ୍ଞା ପାଳନ କର ନାହିଁ। (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- ନିଶ୍ଚୟ ଏହା ଏକ ଉପଦେଶ; ତେଣୁ ଯେ ଇଚ୍ଛା କରେ, ସେ ନିଜ ପ୍ରଭୁଙ୍କ ଆଡ଼କୁ ପଥ ଗ୍ରହଣ କରୁ। (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- ଏବଂ ଯେ କୃତଜ୍ଞତା ପ୍ରକାଶ କରେ, ସେ ନିଜ ପାଇଁ କୃତଜ୍ଞତା ପ୍ରକାଶ କରେ; ଏବଂ ଯେ ଅକୃତଜ୍ଞ ହୁଏ। (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- ଯେଉଁମାନେ ନମାଜ କାୟମ କରନ୍ତି, ଜକାତ ଦିଅନ୍ତି, ଏବଂ ଆଖିରତ ଉପରେ ଦୃଢ଼ ବିଶ୍ୱାସ ରଖନ୍ତି। (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ଇବ୍ରାହିମ, ଇସ୍ମାଇଲ, ଇସହାକ, ଯାକୁବ ଏବଂ ବଂଶଧରମାନଙ୍କୁ, ଏବଂ ମୂସା ଓ ଈସାଙ୍କୁ ଯାହା ଦିଆଯାଇଥିଲା। (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- ଗୋଷ୍ଠୀରେ ଗୋଷ୍ଠୀରେ, ଯେପର୍ଯ୍ୟନ୍ତ ସେମାନେ ସେଠାରେ ପହଞ୍ଚନ୍ତି, ଏବଂ ତା'ର ଦ୍ୱାରଗୁଡ଼ିକ ଖୋଲାଯାଏ, ଏବଂ ତା'ର ରକ୍ଷକମାନେ ସେମାନଙ୍କୁ କୁହନ୍ତି। (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କୁ ତୁମ୍ଭମାନଙ୍କ ଶପଥର ନିରର୍ଥକ କଥା ପାଇଁ ପକଡ଼ କରନ୍ତି ନାହିଁ, କିନ୍ତୁ ସେ ତୁମ୍ଭମାନଙ୍କୁ ତାହା ପାଇଁ ପକଡ଼ କରନ୍ତି। (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- ଦୟା, ସେମାନେ ତାହା ଦ୍ୱାରା ଆନନ୍ଦିତ ହୁଅନ୍ତି, ଏବଂ ଯଦି ସେମାନଙ୍କ ହାତ ପୂର୍ବରୁ ପଠାଇଥିବା କର୍ମ ଯୋଗୁଁ ସେମାନଙ୍କୁ କୌଣସି ଅମଙ୍ଗଳ ସ୍ପର୍ଶ କରେ। (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- ସ୍ୱର୍ଗ ବଗିଚାଗୁଡ଼ିକ ଯାହାର ତଳ ଦେଇ ନଦୀମାନ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ସଦାକାଳ ରହିବେ, ଏବଂ କର୍ମଶୀଳମାନଙ୍କର ପୁରସ୍କାର କେତେ ଉତ୍ତମ! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- ଅଲ୍ଲାହ ଜାଣନ୍ତି ଆକାଶମଣ୍ଡଳରେ ଓ ପୃଥିବୀରେ ଯାହା ଅଛି, ଏବଂ ଅଲ୍ଲାହ। (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- ଅଲ୍ଲାହଙ୍କ ଆଜ୍ଞା ପାଳନ କର ଏବଂ ରସୂଲଙ୍କ ଆଜ୍ଞା ପାଳନ କର; କିନ୍ତୁ ଯଦି ତୁମ୍ଭେମାନେ ମୁହଁ ଫେରାଇ ଦିଅ, ତେବେ ତାଙ୍କ ଉପରେ (ଦାୟିତ୍ୱ) ଅଛି। (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ସେମାନଙ୍କ ପାଇଁ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କ ନିକଟରେ ସେମାନଙ୍କର ପୁରସ୍କାର ଅଛି, ଏବଂ ସେମାନଙ୍କୁ କୌଣସି ଭୟ ନାହିଁ, ଏବଂ ସେମାନେ। (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- ଏବଂ ସେମାନେ କହିଲେ: "ଯେତେବେଳେ ଆମେ ହାଡ଼ ଏବଂ ଧୂଳି ହୋଇଯିବୁ, ସେତେବେଳେ କ'ଣ ଆମେ ନୂତନ ସୃଷ୍ଟି ରୂପେ ଉତ୍ଥିତ ହେବୁ?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- ଏବଂ ସେମାନେ ନିଜ ପାଇଁ ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ କୌଣସି ଅଭିଭାବକ କିମ୍ବା ସହାୟକ ପାଆନ୍ତି ନାହିଁ। (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "ତୁମ୍ଭେ କେତେ ଦିନ ରହିଲ?" ସେ କହିଲା: "ମୁଁ ଦିନେ କିମ୍ବା ଦିନର କିଛି ଅଂଶ ରହିଲି।" ସେ କହିଲା। (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- କ୍ୟାମତ ଦିନ ପର୍ଯ୍ୟନ୍ତ, ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ କିଏ ଦେବ ଯେ ତୁମ୍ଭମାନଙ୍କ ନିକଟକୁ ଆଣିପାରେ? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ଯେ ସତ୍କର୍ମ କରେ, ପୁରୁଷ ହେଉ କିମ୍ବା ନାରୀ, ଏବଂ ସେ ମୋମିନ। (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ଯେଉଁମାନେ ଅଲ୍ଲାହଙ୍କ ପଥରୁ ରୋକନ୍ତି ଏବଂ ତାହାକୁ ବକ୍ର କରିବାକୁ ଚାହାନ୍ତି, ଏବଂ ସେମାନେ ଆଖିରତଠାରୁ। (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ଯେଉଁଠାରେ ଇଚ୍ଛା ସେଠାରେ ଖାଅ, କିନ୍ତୁ ଏହି ଗଛ ନିକଟକୁ ଯାଅ ନାହିଁ, ଅନ୍ୟଥା ତୁମ୍ଭେମାନେ ଅତ୍ୟାଚାରୀ ହୋଇଯିବ। (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- କୁହ: "ହେ ମୋର ସମ୍ପ୍ରଦାୟ! ତୁମ୍ଭେମାନେ ନିଜ ନିଜ ସ୍ଥାନରେ କାର୍ଯ୍ୟ କର, ମୁଁ ମଧ୍ୟ କାର୍ଯ୍ୟ କରୁଛି, ଶୀଘ୍ର ତୁମ୍ଭେମାନେ ଜାଣିବ।" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- ନିଶ୍ଚୟ କ୍ଷତିଗ୍ରସ୍ତ ସେମାନେ ଯେଉଁମାନେ କ୍ୟାମତ ଦିନ ନିଜକୁ ଏବଂ ନିଜ ପରିବାରକୁ କ୍ଷତି କରନ୍ତି, ସାବଧାନ। (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ଯେ ସଠିକ୍ ପଥ ପ୍ରାପ୍ତ ହୁଏ, ସେ ନିଜ ପାଇଁ ସଠିକ୍ ପଥ ପ୍ରାପ୍ତ ହୁଏ; ଏବଂ ଯେ ବିଚ୍ୟୁତ ହୁଏ, ସେ ନିଜ ପାଇଁ ବିଚ୍ୟୁତ ହୁଏ; ଏବଂ। (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- ଏବଂ କାଫିରମାନେ କୁହନ୍ତି: "ତାଙ୍କ ପ୍ରଭୁଙ୍କ ତରଫରୁ ତାଙ୍କ ନିକଟକୁ କାହିଁକି କୌଣସି ନିଦର୍ଶନ ଅବତୀର୍ଣ୍ଣ ହେଲା ନାହିଁ?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ସେ ଯେ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ରାତ୍ରି ସୃଷ୍ଟି କଲେ ଯାହା ଦ୍ୱାରା ତୁମ୍ଭେମାନେ ବିଶ୍ରାମ ନେବ, ଏବଂ ଦିବସ ଯାହା ଦ୍ୱାରା ତୁମ୍ଭେମାନେ ଦେଖିବ, ନିଶ୍ଚୟ। (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ସେହି ଦିନ ଆସିବା ପୂର୍ବରୁ ଯେଉଁଥିରେ କୌଣସି କିଣାବିକା କିମ୍ବା ବନ୍ଧୁତା ନାହିଁ। (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- ଯାହା ଦ୍ୱାରା ସେମାନେ ଚିନ୍ତା କରିବେ ଯେ ସେମାନଙ୍କ ସାଥୀ ପାଗଳ ନୁହଁନ୍ତି; ସେ କେବଳ ଜଣେ ସତର୍କକାରୀ। (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- ସେଠାରେ ସେମାନେ ସଦାକାଳ ରହିବେ, ସେମାନଙ୍କଠାରୁ ଶାସ୍ତି ହ୍ରାସ କରାଯିବ ନାହିଁ, ଏବଂ ସେମାନଙ୍କୁ ଅବକାଶ ଦିଆଯିବ ନାହିଁ। (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ଆମେ ସେମାନଙ୍କ ମଧ୍ୟରୁ କେତେକଙ୍କୁ ଉପଭୋଗ ପାଇଁ ଯାହା ଦେଇଛୁ, ତାହା ପ୍ରତି ତୁମ୍ଭର ଦୃଷ୍ଟି ନ ରଖ। (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ଏବଂ ଲୋକମାନଙ୍କୁ ସେମାନଙ୍କର ଜିନିଷଗୁଡ଼ିକରେ କମ୍ ଦେବ ନାହିଁ, ଏବଂ ପୃଥିବୀରେ ଅଶାନ୍ତି ସୃଷ୍ଟି କର ନାହିଁ। (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- ଏବଂ ତାଙ୍କ ଉପରେ ଶାନ୍ତି ବର୍ଷୁ ଯେଉଁ ଦିନ ସେ ଜନ୍ମ ନେଲେ, ଯେଉଁ ଦିନ ସେ ମୃତ୍ୟୁ ବରଣ କରିବେ, ଏବଂ ଯେଉଁ ଦିନ ସେ ଜୀବିତ ଅବସ୍ଥାରେ ପୁନରୁତ୍ଥିତ ହେବେ। (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- ହେ ମୋର ସମ୍ପ୍ରଦାୟ! ତୁମ୍ଭେମାନେ ନିଜ ନିଜ ସ୍ଥାନରେ କାର୍ଯ୍ୟ କର, ମୁଁ ମଧ୍ୟ କାର୍ଯ୍ୟ କରୁଛି, ଶୀଘ୍ର ତୁମ୍ଭେମାନେ ଜାଣିବ କିଏ। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- ଏବଂ କୌଣସି ରସୂଲଙ୍କ ପାଇଁ ଅଲ୍ଲାହଙ୍କ ଅନୁମତି ବିନା କୌଣସି ନିଦର୍ଶନ ଆଣିବା ସମ୍ଭବ ନଥିଲା। (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ତା'ପରେ ପ୍ରତ୍ୟେକ ବ୍ୟକ୍ତିଙ୍କୁ ସେ ଅର୍ଜନ କରିଥିବା ଜିନିଷର ସମ୍ପୂର୍ଣ୍ଣ ପ୍ରତିଫଳ ଦିଆଯିବ, ଏବଂ ସେମାନଙ୍କ ଉପରେ ଅତ୍ୟାଚାର କରାଯିବ ନାହିଁ। (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ପୁରୁଷ ହେଉ କିମ୍ବା ନାରୀ, ଏବଂ ସେ ମୋମିନ, ତେବେ ସେମାନେ ସ୍ୱର୍ଗରେ ପ୍ରବେଶ କରିବେ। (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ସେ କୌଣସି ସନ୍ତାନ ଗ୍ରହଣ କରିନାହାନ୍ତି ଏବଂ ରାଜ୍ୟରେ ତାଙ୍କର କୌଣସି ଭାଗୀଦାର ନାହିଁ। (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- ଏବଂ ଅଲ୍ଲାହ ଯାହାକୁ ସଠିକ୍ ପଥ ଦେଖାନ୍ତି, ସେ ସଠିକ୍ ପଥ ପ୍ରାପ୍ତ; ଏବଂ ଯାହାକୁ ସେ ବିଚ୍ୟୁତ କରନ୍ତି। (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- ଦେଖ, ସେମାନେ ତୁମ୍ଭ ପାଇଁ କିପରି ଦୃଷ୍ଟାନ୍ତ ଦିଅନ୍ତି, ତେଣୁ ସେମାନେ ବିଚ୍ୟୁତ ହେଲେ, ଏବଂ ସେମାନେ ପଥ ପାଇଲେ ନାହିଁ। (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- କୁହ: "ଯଦି ମୁଁ ମୋର ପ୍ରଭୁଙ୍କ ଅବଜ୍ଞା କରେ, ତେବେ ମୁଁ ମହାଦିନର ଶାସ୍ତିକୁ ଭୟ କରେ।" (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- ସେମାନଙ୍କର ଲଜ୍ଜା ସ୍ଥାନଗୁଡ଼ିକ ଖୋଲା ହୋଇଗଲା, ଏବଂ ସେମାନେ ସ୍ୱର୍ଗର ପତ୍ରଗୁଡ଼ିକ ଦ୍ୱାରା ନିଜକୁ ଘୋଡ଼ାଇବାକୁ ଲାଗିଲେ। (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- ଏବଂ ଅଲ୍ଲାହଙ୍କ ବ୍ୟତୀତ ତୁମ୍ଭେମାନେ ଯାହାକୁ ଡାକିପାର ତାହାକୁ ଡାକ, ଯଦି ତୁମ୍ଭେମାନେ ସତ୍ୟବାଦୀ ହୁଅ। (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- ପୃଥିବୀର ସମସ୍ତ ଜିନିଷ ଏବଂ ତା' ସହିତ ସେତିକି ଅଧିକ, ଯାହା ଦ୍ୱାରା ସେମାନେ ନିଜକୁ ମୁକ୍ତ କରିବେ। (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ଆମେ ତୁମ୍ଭମାନଙ୍କୁ ଯାହା ଦେଇଛୁ ତାହା ଦୃଢ଼ ଭାବରେ ଧର, ଏବଂ ତହିଁରେ ଯାହା ଅଛି ତାହା ସ୍ମରଣ କର, ଯାହା ଦ୍ୱାରା ତୁମ୍ଭେମାନେ ସଂଯମୀ ହୋଇପାର। (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ତୁମ୍ଭେମାନେ କ'ଣ ସେହି ଅଶ୍ଳୀଳ କାର୍ଯ୍ୟ କରୁଛ ଯାହା ତୁମ୍ଭମାନଙ୍କ ପୂର୍ବରୁ ବିଶ୍ୱବାସୀମାନଙ୍କ ମଧ୍ୟରୁ କେହି କରି ନାହିଁ? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- ଏବଂ ଅଲ୍ଲାହଙ୍କ ପାଇଁ ଆକାଶମଣ୍ଡଳରେ ଓ ପୃଥିବୀରେ ଯାହା ଅଛି, ଏବଂ ଅଲ୍ଲାହ। (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- ସେମାନେ କରିଥିବା ପାପଗୁଡ଼ିକ ସେମାନଙ୍କୁ ଘେରି ରହିଲା, ଏବଂ ସେମାନେ ଯାହାର ଉପହାସ କରୁଥିଲେ ତାହା ସେମାନଙ୍କୁ ଆବର୍ତ୍ତନ କଲା। (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- ତୁମ୍ଭମାନଙ୍କ ମଧ୍ୟରୁ ଜଣେ ରସୂଲ, ଯେ ତୁମ୍ଭମାନଙ୍କୁ ଆମର ଆୟତଗୁଡ଼ିକ ପଢ଼ି ଶୁଣାନ୍ତି, ତୁମ୍ଭମାନଙ୍କୁ ପବିତ୍ର କରନ୍ତି, ଏବଂ ତୁମ୍ଭମାନଙ୍କୁ କିତାବ ଓ ହିକମତ ଶିକ୍ଷା ଦିଅନ୍ତି। (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- ତାହା ମଧ୍ୟରୁ ବାରଟି ଝରଣା ବୋହିଲା; ପ୍ରତ୍ୟେକ ଗୋଷ୍ଠୀ ନିଜର ପାନୀୟ ସ୍ଥାନ ଜାଣିପାରିଲା। (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- କେବଳ ଅନୁମାନ, ଏବଂ ନିଶ୍ଚୟ ଅନୁମାନ ସତ୍ୟ ବିଷୟରେ କୌଣସି କାମରେ ଆସେ ନାହିଁ। (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- ଯେତେବେଳେ ମୁଁ ତାକୁ ସୁସଂହତ କରିବି ଏବଂ ତହିଁରେ ମୋର ଆତ୍ମା ଫୁଙ୍କିବି, ସେତେବେଳେ ତୁମ୍ଭେମାନେ ତାଙ୍କୁ ସଜଦା କର। (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- ଏହି ଗୃହର ଉତ୍ତମ ପରିଣାମ କାହାର? ନିଶ୍ଚୟ ଅତ୍ୟାଚାରୀମାନେ ସଫଳ ହୁଅନ୍ତି ନାହିଁ। (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- ସେ ଯେ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀ ସୃଷ୍ଟି କରିଛନ୍ତି, ସେ ସେମାନଙ୍କ ପରି ସୃଷ୍ଟି କରିବାକୁ ସକ୍ଷମ। (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- ମୋମିନ ପୁରୁଷ ଓ ମୋମିନ ସ୍ତ୍ରୀମାନଙ୍କ ପାଇଁ ସ୍ୱର୍ଗ ବଗିଚାଗୁଡ଼ିକ ଅଛି ଯାହାର ତଳ ଦେଇ ନଦୀମାନ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ସଦାକାଳ ରହିବେ। (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- ଏବଂ ଯଦି ତୁମ୍ଭେ ସେମାନଙ୍କୁ ପଚାର ଯେ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀ କିଏ ସୃଷ୍ଟି କରିଛି, ସେମାନେ ନିଶ୍ଚୟ "ଅଲ୍ଲାହ" କହିବେ; କୁହ। (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- ଏବଂ ନିଶ୍ଚୟ ଆମେ ଏହି କୁରଆନରେ ଲୋକମାନଙ୍କ ପାଇଁ ସବୁ ପ୍ରକାର ଦୃଷ୍ଟାନ୍ତ ଦେଇଛୁ। (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- ଯେତେବେଳେ ଆମର ରସୂଲମାନେ ଲୂତଙ୍କ ନିକଟକୁ ଆସିଲେ, ସେ ସେମାନଙ୍କ କାରଣରେ ଦୁଃଖିତ ହେଲେ ଏବଂ ସଙ୍କୁଚିତ ହେଲେ, ଏବଂ କହିଲେ। (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- ଏବଂ ଯେତେବେଳେ ଆମେ ଫିରିଶ୍ତାମାନଙ୍କୁ କହିଲୁ: "ଆଦମଙ୍କୁ ସଜଦା କର," ସେମାନେ ସଜଦା କଲେ, ଇବ୍ଲୀସ ବ୍ୟତୀତ, ସେ ଅସ୍ୱୀକାର କଲା। (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
- ଏବଂ ପୃଥିବୀକୁ ଆମେ ବିସ୍ତୃତ କଲୁ, ଏବଂ ତହିଁରେ ପର୍ବତମାନ ସ୍ଥାପନ କଲୁ, ଏବଂ ତହିଁରେ ସବୁ ପ୍ରକାର ସୁନ୍ଦର ବସ୍ତୁ ଉତ୍ପନ୍ନ କଲୁ। (وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ) 15:19; 50:7
