- ଅଲ୍ଲାହ ସେମାନଙ୍କ ଉପରେ ଅତ୍ୟାଚାର କଲେ ନାହିଁ, ବରଂ ସେମାନେ ନିଜ ଉପରେ ଅତ୍ୟାଚାର କରୁଥିଲେ। (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- ସେ ତମମାନଙ୍କର ପାପ କ୍ଷମା କରିବେ ଏବଂ ତମମାନଙ୍କୁ ସେପରି ସ୍ୱର୍ଗବଗିଚାଗୁଡ଼ିକରେ ପ୍ରବେଶ କରାଇବେ, ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ। (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- ସେ ତମମାନଙ୍କ ପାଇଁ ମୃତପ୍ରାଣୀ, ରକ୍ତ, ଘୁଷୁରୀ ମାଂସ ଏବଂ ଯାହା ଅଲ୍ଲାହ ବ୍ୟତୀତ ଅନ୍ୟର ନାମରେ ବଳି ଦିଆଯାଏ, ତାହା ହରାମ କରିଛନ୍ତି। (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- ଯଦି ମୁଁ ମୋ ପ୍ରଭୁଙ୍କ ଅବଜ୍ଞା କରେ, ତେବେ ମୁଁ ମହାଦିନର ଶିକ୍ଷାକୁ ଭୟ କରେ। (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- କିନ୍ତୁ ସେମାନଙ୍କ ନିକଟରେ ଜ୍ଞାନ ଆସିବା ପରେ, ପରସ୍ପର ମଧ୍ୟରେ ଈର୍ଷ୍ୟା ଯୋଗୁଁ। (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- ସେମାନେ ନମାଜ ପ୍ରତିଷ୍ଠା କରନ୍ତି ଏବଂ ଆମେ ସେମାନଙ୍କୁ ଯାହା ଦେଇଛୁ, ତାହାରୁ ଗୋପନରେ ଓ ପ୍ରକାଶ୍ୟରେ ବ୍ୟୟ କରନ୍ତି। (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- କ'ଣ ଆମେ ଅଲ୍ଲାହଙ୍କୁ ଛାଡ଼ି ସେପରି ବ୍ୟକ୍ତିଙ୍କୁ ଡାକିବା, ଯିଏ ଆମକୁ ନ ଲାଭ ଦେଇପାରେ ଓ ନ କ୍ଷତି? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- ସେମାନେ ତୁମ ପ୍ରତି ଅବତୀର୍ଣ୍ଣ କରାଯାଇଥିବା ବିଷୟ ଏବଂ ତୁମ ପୂର୍ବରୁ ଅବତୀର୍ଣ୍ଣ କରାଯାଇଥିବା ବିଷୟରେ ଈମାନ ଆଣନ୍ତି। (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- ତୁମେ କ'ଣ ଦେଖୁନାହଁ ଯେ ଅଲ୍ଲାହ ଆକାଶରୁ ଜଳ ବର୍ଷାନ୍ତି? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- ଯେତେବେଳେ ସେ କୌଣସି କାର୍ଯ୍ୟର ନିର୍ଣ୍ଣୟ କରନ୍ତି, ସେତେବେଳେ ତାକୁ କୁହନ୍ତି: ହୋଇଯାଅ, ତେବେ ସେ ହୋଇଯାଏ। (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- ଆମେ ମଦ୍ୟନ ପ୍ରତି ସେମାନଙ୍କ ଭାଇ ଶୁଆଇବଙ୍କୁ (ପଠାଇଲୁ)। ସେ କହିଲେ: ହେ ମୋ ଜାତିଲୋକେ! ଅଲ୍ଲାହଙ୍କର ଉପାସନା କର। (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- ଏହା ଅଦୃଶ୍ୟ ସମ୍ବାଦ ମଧ୍ୟରୁ ଅଟେ, ଯାହାକୁ ଆମେ ତୁମ ପ୍ରତି ପ୍ରେରଣ କରୁଛୁ; ତୁମେ ଏହା ଜାଣି ନ ଥିଲ। (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- ଯେତେବେଳେ ସେମାନଙ୍କର ନିର୍ଦ୍ଧାରିତ ସମୟ ଆସେ, ସେତେବେଳେ ସେମାନେ ଗୋଟିଏ ଘଣ୍ଟା ବିଳମ୍ବ କରିପାରନ୍ତି ନାହିଁ, କିମ୍ବା ଆଗକୁ ବଢ଼ାଇପାରନ୍ତି ନାହିଁ। (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- ତମେ ଶୟତାନର ପଦାଙ୍କ ଅନୁସରଣ କରନାହିଁ, ନିଶ୍ଚୟ ସେ ତମର ପ୍ରକଟ ଶତ୍ରୁ। (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- ମନୁଷ୍ୟମାନଙ୍କ ମଧ୍ୟରୁ କେହି କେହି ଅଜ୍ଞାନତାରେ ଅଲ୍ଲାହଙ୍କ ବିଷୟରେ ବିତର୍କ କରନ୍ତି। (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- ଅଲ୍ଲାହ ଯାହାକୁ ଚାହାନ୍ତି ତାକୁ ଦିଅନ୍ତି, ଏବଂ ଅଲ୍ଲାହ ମହାନ କୃପାଶୀଳ। (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ପ୍ରତ୍ୟେକ ବ୍ୟକ୍ତିକୁ ତା'ର କର୍ମର ପୂର୍ଣ ପ୍ରତିଦାନ ଦିଆଯିବ, ଏବଂ ସେମାନଙ୍କ ଉପରେ ଅତ୍ୟାଚାର କରାଯିବ ନାହିଁ। (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- ଅଲ୍ଲାହ ଯେଉଁ ପ୍ରାଣକୁ ନିଷିଦ୍ଧ କରିଛନ୍ତି, ତାକୁ ନ୍ୟାୟ ବିନା ହତ୍ୟା କରନାହିଁ। (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- ଯେତେବେଳେ ସେ କୌଣସି କାର୍ଯ୍ୟର ନିର୍ଣ୍ଣୟ କରନ୍ତି, ସେତେବେଳେ ତାକୁ କୁହନ୍ତି: ହୋଇଯାଅ। (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- ତମେ ଜାହନ୍ନମର ଦ୍ୱାରଗୁଡ଼ିକ ମାଧ୍ୟମରେ ପ୍ରବେଶ କର, ସେଠାରେ ଚିରଦିନ ରହିବ; ଅହଙ୍କାରୀମାନଙ୍କର ବାସସ୍ଥାନ କେତେ ନର୍ତ୍ତକ! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ତୁମେ କ'ଣ ସେହି ଲୋକମାନଙ୍କୁ ଦେଖିନାହଁ, ଯେଉଁମାନଙ୍କୁ କିତାବର କିଛି ଅଂଶ ଦିଆଯାଇଥିଲା? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- ସେମାନଙ୍କ ପାଇଁ ସେପରି ସ୍ୱର୍ଗବଗିଚାଗୁଡ଼ିକ ଅଛି, ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ଚିରଦିନ ରହିବେ। (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- ହେ ମୋ ଜାତିଲୋକେ! ତମେ ନିଜ ସ୍ଥାନରେ କାର୍ଯ୍ୟ କର, ମୁଁ ମଧ୍ୟ କାର୍ଯ୍ୟ କରୁଛି, ଏବଂ ଶୀଘ୍ର ତମେ ଜାଣିପାରିବ। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- ଯେ ଅଲ୍ଲାହ ଏବଂ ତାଙ୍କ ରସୂଲଙ୍କର ବିରୋଧ କରେ, ତା' ପାଇଁ ଜାହନ୍ନମର ଅଗ୍ନି ଅଛି, ସେଠାରେ ସେ ଚିରଦିନ ରହିବ। (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- ଆମେ ସେମାନଙ୍କ ହୃଦୟ ଉପରେ ପରଦା ଦେଇଛୁ, ଯେପରି ସେମାନେ ତାହା ବୁଝିପାରିବେ ନାହିଁ, ଏବଂ ସେମାନଙ୍କ କର୍ଣ୍ଣରେ ବଧିରତା। (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- ଆମେ ଯେଉଁ ବସ୍ତିରେ ସତର୍କକାରୀ ପଠାଇଥାଉ, ସେଠାରେ ଧନୀ ଲୋକମାନେ କହିଥାନ୍ତି: ଆମେ। (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- ସେମାନେ କହିଲେ: ଆମ ପାଇଁ ତୁମର ପ୍ରଭୁଙ୍କୁ ପ୍ରାର୍ଥନା କର, ଯେପରି ସେ ଆମକୁ ସ୍ପଷ୍ଟ କରି ଦେବେ ଯେ ତାହା କ'ଣ। (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- ସେମାନେ ନିଶ୍ଚୟ କହିବେ: ଅଲ୍ଲାହ। କୁହ: ସମସ୍ତ ପ୍ରଶଂସା ଅଲ୍ଲାହଙ୍କ ପାଇଁ! କିନ୍ତୁ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଅଧିକାଂଶ। (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- ତାଙ୍କ ଜାତିର ଉତ୍ତର କେବଳ ଏହି ଥିଲା ଯେ ସେମାନେ କହିଲେ: ସେମାନଙ୍କୁ ବାହାର କରିଦିଅ। (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ଚିରଦିନ ରହିବେ; ଏହା ହିଁ ମହାନ ସଫଳତା। (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- ସେମାନେ ତାଙ୍କ ପ୍ରଭୁଙ୍କ ତରଫରୁ ପଥପ୍ରଦର୍ଶନରେ ଅଛନ୍ତି, ଏବଂ ସେମାନେ ହିଁ ସଫଳକାମୀ। (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- ଯାହାକୁ ଅପମାନଜନକ ଶିକ୍ଷା ଆସିପହଞ୍ଚେ ଏବଂ ଯାହା ଉପରେ ସ୍ଥାୟୀ ଶିକ୍ଷା ପଡ଼େ। (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- ପୃଥିବୀରେ ଭ୍ରମଣ କର ଏବଂ ଦେଖ ଯେ (ସତ୍ୟକୁ) ମିଥ୍ୟା ପ୍ରତିପାଦନ କରୁଥିବାମାନଙ୍କର ପରିଣାମ କିପରି ହୋଇଥିଲା। (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- ସେମାନେ କେବେବି ତାହା କାମନା କରିବେ ନାହିଁ, ସେମାନଙ୍କ ହାତ ଯାହା ଆଗକୁ ପଠାଇଛି, ତା' ଯୋଗୁଁ, ଏବଂ ଅଲ୍ଲାହ ଅତ୍ୟାଚାରୀମାନଙ୍କୁ ଭଲ ଭାବରେ ଜାଣନ୍ତି। (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- ସେ ଭଲ ଭାବରେ ଜାଣନ୍ତି ଯେ କିଏ ତାଙ୍କ ପଥରୁ ପଥଭ୍ରଷ୍ଟ ହୋଇଛି, ଏବଂ ସେ ଭଲ ଭାବରେ ଜାଣନ୍ତି। (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- ଅଲ୍ଲାହ ହିଁ ମୋ'ର ପ୍ରଭୁ ଏବଂ ତମମାନଙ୍କର ପ୍ରଭୁ, ତେଣୁ ତାଙ୍କର ଉପାସନା କର; ଏହା ହିଁ ସଳଖ ପଥ। (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- ସେ ମନୁଷ୍ୟଙ୍କ ପ୍ରତି ଅତ୍ୟନ୍ତ ଦୟାଳୁ, କିନ୍ତୁ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଅଧିକାଂଶ କୃତଜ୍ଞତା ପ୍ରକାଶ କରନ୍ତି ନାହିଁ। (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- ଆକାଶମଣ୍ଡଳ, ପୃଥିବୀ ଏବଂ ସେମାନଙ୍କ ମଧ୍ୟବର୍ତ୍ତୀ ସମସ୍ତ ବସ୍ତୁ, ଆମେ ସତ୍ୟ ଏବଂ ନିର୍ଦ୍ଧାରିତ ସମୟ ପାଇଁ ସୃଷ୍ଟି କରିଛୁ। (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ସେମାନଙ୍କୁ ସେମାନଙ୍କ ନିରର୍ଥକ କଥା ଏବଂ ଖେଳରେ ଛାଡ଼ି ଦିଅ, ଯେ ପର୍ଯ୍ୟନ୍ତ ସେମାନେ ସେମାନଙ୍କ ସେହି ଦିନକୁ ଦେଖା କରନ୍ତି, ଯାହାର ପ୍ରତିଶ୍ରୁତି ସେମାନଙ୍କୁ ଦିଆଯାଇଛି। (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- ଯେତେବେଳେ ସେମାନେ ଈମାନଦାରମାନଙ୍କୁ ଭେଟନ୍ତି, କହନ୍ତି: ଆମେ ଈମାନ ଆଣିଲୁ, ଏବଂ ଯେତେବେଳେ ସେମାନେ ପରସ୍ପର ସହିତ ଏକାନ୍ତରେ ଥାଆନ୍ତି। (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- ସେମାନେ ତୌରାତ, ଇଞ୍ଜୀଲ ଏବଂ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କ ତରଫରୁ ସେମାନଙ୍କ ପ୍ରତି ଯାହା ଅବତୀର୍ଣ୍ଣ କରାଯାଇଛି, ତାହା ପ୍ରତିଷ୍ଠା କରନ୍ତି। (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- ସେ ଜାଣନ୍ତି ସେମାନଙ୍କ ସମ୍ମୁଖରେ ଯାହା ଅଛି ଏବଂ ସେମାନଙ୍କ ପୃଷ୍ଠଭାଗରେ ଯାହା ଅଛି, ଏବଂ ସେମାନେ ତାହାକୁ ନିଜ ଜ୍ଞାନରେ ଆବଦ୍ଧ କରିପାରିବେ ନାହିଁ। (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- ଏବଂ ସେ ହିଁ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀକୁ ଛଅ ଦିନରେ ସୃଷ୍ଟି କଲେ। (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- ନିଶ୍ଚୟ ସେଥିରେ ତମମାନଙ୍କ ପାଇଁ ଏକ ନିଦର୍ଶନ ଅଛି, ଯଦି ତମେ ଈମାନଦାର ହୋଇଥାଅ। (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- ଲୋକମାନଙ୍କ ନିକଟରେ ପଥପ୍ରଦର୍ଶନ ଆସିବା ପରେ ସେମାନଙ୍କୁ ଈମାନ ଆଣିବାରୁ କ'ଣ ରୋକିଲା? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- ସେମାନେ ଅଲ୍ଲାହଙ୍କ ସହିତ ଅଂଶୀଦାର ସ୍ଥାପନ କଲେ, ଯାହାଫଳରେ ତାଙ୍କ ପଥରୁ ପଥଭ୍ରଷ୍ଟ କରାଯାଏ। କୁହ: ତମେ ଉପଭୋଗ କର। (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- ସେମାନେ ଆଶ୍ଚର୍ଯ୍ୟ ହେଲେ ଯେ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଜଣେ ସତର୍କକାରୀ ସେମାନଙ୍କ ନିକଟକୁ ଆସିଲା, ଏବଂ କାଫିରମାନେ କହିଲେ: ଏହି। (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- ତୁମ ପ୍ରଭୁ ଭଲ ଭାବରେ ଜାଣନ୍ତି ଯେ କିଏ ତାଙ୍କ ପଥରୁ ପଥଭ୍ରଷ୍ଟ ହୋଇଛି। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- ସେହି ବ୍ୟକ୍ତି ପରି, ଯେ ନିଜ ସମ୍ପତ୍ତି ଲୋକମାନଙ୍କୁ ଦେଖାଇବା ପାଇଁ ବ୍ୟୟ କରେ ଏବଂ ଅଲ୍ଲାହଙ୍କ ଉପରେ ଈମାନ ଆଣେ ନାହିଁ। (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- ଆମେ ତମମାନଙ୍କୁ ଯାହା ଦେଇଛୁ, ତାହାରୁ ସେହି (ଦିନ) ଆସିବା ପୂର୍ବରୁ ବ୍ୟୟ କର। (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- ସେ ଆକାଶମଣ୍ଡଳରେ ଏବଂ ପୃଥିବୀରେ ଯାହା କିଛି ଅଛି, ତମମାନଙ୍କ ପାଇଁ ବଶୀଭୂତ କରିଦେଇଛନ୍ତି। (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- ଆମେ ତ ଯାହା ପ୍ରତି ତମେ ଆମକୁ ଡାକୁଛ, ତାହା ବିଷୟରେ ସନ୍ଦେହରେ ଅଛୁ। (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- ତୁମ ପ୍ରଭୁ ଯାହାକୁ ଇଚ୍ଛା କରନ୍ତି, ତାକୁ ଜୀବିକା ପ୍ରଶସ୍ତ କରିଦିଅନ୍ତି ଏବଂ ସଂକୁଚିତ ମଧ୍ୟ କରିଦିଅନ୍ତି। ନିଶ୍ଚୟ ସେ। (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- ଆକାଶମଣ୍ଡଳ, ପୃଥିବୀ ଏବଂ ସେମାନଙ୍କ ମଧ୍ୟବର୍ତ୍ତୀ ସମସ୍ତ ବସ୍ତୁର ପ୍ରଭୁ, ଯଦି ତମେ ବିଶ୍ୱାସୀ ହୋଇଥାଅ। (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- ଆମେ ଅଲ୍ଲାହଙ୍କ ଉପରେ ଈମାନ ଆଣିଲୁ ଏବଂ ଯାହା ଆମ ପ୍ରତି ଅବତୀର୍ଣ୍ଣ କରାଯାଇଛି, ଏବଂ ଯାହା (ଇବ୍ରାହିମ, ଇସ୍ମାଇଲ, ଇସ୍ହାକ, ୟାକୂବ ଏବଂ ତାଙ୍କ ବଂଶଧରମାନଙ୍କ ପ୍ରତି) ଅବତୀର୍ଣ୍ଣ କରାଯାଇଥିଲା। (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- ଅତ୍ୟାଚାରୀମାନଙ୍କୁ ଭୟଙ୍କର ଚିତ୍କାର ଆକ୍ରମଣ କଲା, ଫଳରେ ସେମାନେ ନିଜ ଘରେ ଓଲଟା ପଡ଼ି ରହିଲେ। (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- ସେହି ସ୍ତ୍ରୀମାନେ ନିଜ ବିଷୟରେ ଯାହା କରନ୍ତି, ତାହା ପାଇଁ ତମମାନଙ୍କ ଉପରେ କୌଣସି ପାପ ନାହିଁ। (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- ତୁମ ପ୍ରଭୁ ଭଲ ଭାବରେ ଜାଣନ୍ତି ଯେ କିଏ ତାଙ୍କ ପଥରୁ ପଥଭ୍ରଷ୍ଟ ହୋଇଛି, ଏବଂ ସେ। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- ତାଙ୍କ ଆଦେଶରେ ରୂହ (ପ୍ରକାଶନା) ଆପଣା ବନ୍ଦାମାନଙ୍କ ମଧ୍ୟରୁ ଯାହାକୁ ଇଚ୍ଛା କରନ୍ତି, ତା' ଉପରେ ଅବତୀର୍ଣ୍ଣ କରନ୍ତି। (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- ଆମେ ମର୍ୟମଙ୍କ ପୁତ୍ର ଈସାଙ୍କୁ ସ୍ପଷ୍ଟ ନିଦର୍ଶନ ଦେଇଥିଲୁ ଏବଂ ପବିତ୍ର ଆତ୍ମା ଦ୍ୱାରା ତାଙ୍କୁ ସମର୍ଥନ ଦେଇଥିଲୁ। (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- ଯାହାଫଳରେ ପୁନରୁତ୍ଥାନ ଦିନ ସେମାନଙ୍କ ମଧ୍ୟରେ, ଯେଉଁ ବିଷୟରେ ସେମାନେ ମତଭେଦ କରୁଥିଲେ, ତାହାର ଫଇସଲା କରିବେ। (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ଆମେ ସେହି (ନଗର) ର ଉପର ଭାଗକୁ ତଳ କରିଦେଲୁ ଏବଂ ସେମାନଙ୍କ ଉପରେ ପୋଡ଼ା ମାଟିର ପଥର ବର୍ଷାଇଲୁ। (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- ସେମାନଙ୍କ ପାଇଁ ସମାନ, ତୁମେ ସେମାନଙ୍କୁ ସତର୍କ କର କିମ୍ବା ନ କର, ସେମାନେ ଈମାନ ଆଣିବେ ନାହିଁ। (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- ଲୋକମାନଙ୍କୁ ଛାଡ଼ି, ଯଦି ତମେ ସତ୍ୟବାଦୀ ହୋଇଥାଅ, ତେବେ ମୃତ୍ୟୁର କାମନା କର। (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- ଅଲ୍ଲାହଙ୍କ (ଉପାସନା କର), ତାଙ୍କ ବ୍ୟତୀତ ତମର କୌଣସି ଉପାସ୍ୟ ନାହିଁ। ତଥାପି କ'ଣ ତମେ ଭୟ କରୁନାହଁ? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- ଆମେ ସେମାନଙ୍କୁ ଯେଉଁ ଶିକ୍ଷାର ଧମକ ଦେଉଛୁ, ତାହାର କିଛି ଅଂଶ ତୁମକୁ ଦେଖାଇବୁ, କିମ୍ବା ତୁମକୁ ମୃତ୍ୟୁ ଦେବୁ, ସେମାନଙ୍କର ପ୍ରତ୍ୟାବର୍ତ୍ତନ ତ ଆମ ପାଖକୁ। (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- ସେମାନେ କହିଲେ: କ'ଣ ଯେତେବେଳେ ଆମେ ମରିଯାଇ ମାଟି ଏବଂ ହାଡ଼ ହୋଇଯିବୁ, ତେବେ କ'ଣ ଆମେ ପୁନର୍ଜୀବିତ ହେବୁ? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- ନିଶ୍ଚୟ କୃପା ଅଲ୍ଲାହଙ୍କ ହାତରେ, ସେ ଯାହାକୁ ଇଚ୍ଛା କରନ୍ତି ତାକୁ ଦିଅନ୍ତି, ଏବଂ ଅଲ୍ଲାହ। (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- ଏବଂ ତମେ ଗୁପ୍ତ ଓ ପ୍ରକାଶ୍ୟର ଜ୍ଞାତାଙ୍କ ନିକଟକୁ ପ୍ରତ୍ୟାବର୍ତ୍ତିତ ହେବ, ତା'ପରେ ସେ ତମମାନଙ୍କୁ ତମମାନଙ୍କ କର୍ମ ବିଷୟରେ ଜଣାଇବେ। (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- ହେ ଈମାନଦାରମାନେ! ଅଲ୍ଲାହଙ୍କ ସେହି ଅନୁଗ୍ରହକୁ ସ୍ମରଣ କର, ଯେତେବେଳେ। (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- ଆମେ ତୁମ ପୂର୍ବରୁ ମଧ୍ୟ କେବଳ ପୁରୁଷମାନଙ୍କୁ ରସୂଲ କରି ପଠାଇଥିଲୁ, ଯେଉଁମାନଙ୍କ ପ୍ରତି ଆମେ ପ୍ରକାଶନା ପଠାଉଥିଲୁ। (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- ସେ ତାଙ୍କ ପାପ କ୍ଷମା କରିବେ ଏବଂ ତାଙ୍କୁ ସେପରି ସ୍ୱର୍ଗବଗିଚାଗୁଡ଼ିକରେ ପ୍ରବେଶ କରାଇବେ, ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ। (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- ଯଦି କେହି ରୋଗୀ କିମ୍ବା ଯାତ୍ରାରେ ଥାଏ, ତେବେ ଅନ୍ୟ ଦିନଗୁଡ଼ିକରେ ସଂଖ୍ୟା ପୂରଣ କରିବ। (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- ସେମାନେ କେବଳ ଅନୁମାନର ଅନୁସରଣ କରନ୍ତି, ଏବଂ ସେମାନେ କେବଳ ଅଟକଳ କରନ୍ତି। (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- ଯେ ଅଲ୍ଲାହ ଏବଂ ଶେଷ ଦିନର ଆଶା ରଖେ, ତା' ପାଇଁ ଉତ୍ତମ ଆଦର୍ଶ ଅଛି। (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- ଏବଂ ଆମେ ଆକାଶମଣ୍ଡଳ, ପୃଥିବୀ ଏବଂ ସେମାନଙ୍କ ମଧ୍ୟବର୍ତ୍ତୀ ସମସ୍ତ ବସ୍ତୁକୁ ସତ୍ୟ ସହିତ ସୃଷ୍ଟି କରିଛୁ। (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- ତୁମ ହାତ ତୁମ ବକ୍ଷରେ ରଖ, ତାହା କୌଣସି ରୋଗ ବିନା ଉଜ୍ଜ୍ୱଳ ହୋଇ ବାହାରି ଆସିବ। (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- ସେ ଆପଣା ଦୟାରେ ଯାହାକୁ ଇଚ୍ଛା କରନ୍ତି, ବାଛି ନିଅନ୍ତି, ଏବଂ ଅଲ୍ଲାହ ମହାନ କୃପାଶୀଳ। (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- ତୁମେ କ'ଣ ଜାଣିନାହଁ ଯେ ଅଲ୍ଲାହଙ୍କ ପାଇଁ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀର ରାଜ୍ୟ? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- ତମେ ନିଜ ପାଇଁ ଯାହା ଭଲ ଆଗକୁ ପଠାଇବ, ତାହା ତମେ ଅଲ୍ଲାହଙ୍କ ନିକଟରେ ପାଇବ। (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- ଏବଂ ତୁମେ ଯେଉଁଠାରୁ ବାହାର, ତୁମ ମୁଖ ମସ୍ଜିଦୁଲ-ହରାମ ଆଡ଼କୁ ଫେରାଅ। (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- ତୁମ ପୂର୍ବବର୍ତ୍ତୀମାନେ (ବିତିଯାଇଛନ୍ତି), ଏବଂ ତୁମେ ଅଲ୍ଲାହଙ୍କ ନିୟମରେ କୌଣସି ପରିବର୍ତ୍ତନ ପାଇବ ନାହିଁ। (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- ଯାହାଙ୍କ ପାଇଁ ଆକାଶମଣ୍ଡଳରେ ଓ ପୃଥିବୀରେ ଯାହା କିଛି ଅଛି, (ସବୁ) ତାଙ୍କର। (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- କୌଣସି ସ୍ତ୍ରୀ ଗର୍ଭଧାରଣ କରେ ନାହିଁ କିମ୍ବା ପ୍ରସବ କରେ ନାହିଁ, ତାଙ୍କ ଜ୍ଞାନ ବିନା। (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- ସେ ରାତ୍ରି, ସୂର୍ଯ୍ୟ ଏବଂ ଚନ୍ଦ୍ରଙ୍କୁ ବଶୀଭୂତ କରିଦେଇଛନ୍ତି; ପ୍ରତ୍ୟେକ ନିର୍ଦ୍ଧାରିତ ସମୟ ପର୍ଯ୍ୟନ୍ତ ଗତି କରେ। (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ଚିରଦିନ ରହିବେ, ଏବଂ ତାହା ହିଁ ପୁରସ୍କାର। (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- ସେ କହିଲେ: ନୁହେଁ, ତମମାନଙ୍କ ମନ ତମମାନଙ୍କ ପାଇଁ ଏକ କାର୍ଯ୍ୟକୁ ସୁଶୋଭିତ କରିଛି; ତେଣୁ ଧୈର୍ଯ୍ୟ ସୁନ୍ଦର। (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- ଆକାଶମଣ୍ଡଳରେ ଓ ପୃଥିବୀରେ ଯାହା ଅଛି, ଏବଂ ନିଶ୍ଚୟ ଅଲ୍ଲାହ। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- ସେମାନଙ୍କ ନିକଟରେ ଯେଉଁ ରସୂଲ ଆସିଲେ, ସେମାନେ ତାଙ୍କୁ ଉପହାସ କରୁଥିଲେ। (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- ସେମାନେ କହିଲେ: ହେ ମୂସା! ତୁମେ ଫୋପାଡ଼ କିମ୍ବା ଆମେ ଫୋପାଡ଼ୁ? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- ସେ ହିଁ ତମମାନଙ୍କୁ ମୃତ୍ୟୁ ଦିଅନ୍ତି, ଏବଂ ତମମାନଙ୍କ ମଧ୍ୟରୁ କିଏ ଅତ୍ୟନ୍ତ ବୃଦ୍ଧ ଅବସ୍ଥାକୁ ଫେରାଇ ଦିଆଯାଏ, ଯାହାଫଳରେ। (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- ସେମାନଙ୍କ ପାଇଁ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କ ନିକଟରେ ସେପରି ସ୍ୱର୍ଗବଗିଚାଗୁଡ଼ିକ ଅଛି, ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ଚିରଦିନ ରହିବେ। (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- ଏବଂ ଆମେ ସେମାନଙ୍କ ହୃଦୟ ଉପରେ ପରଦା ଦେଇଛୁ, ଯେପରି ସେମାନେ ତାହା ବୁଝିପାରିବେ ନାହିଁ, ଏବଂ ସେମାନଙ୍କ କର୍ଣ୍ଣରେ ବଧିରତା। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- ଅଲ୍ଲାହଙ୍କ ପ୍ରତିଜ୍ଞା ସତ୍ୟ, କିନ୍ତୁ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଅଧିକାଂଶ ଜାଣନ୍ତି ନାହିଁ। (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- ଏହା କାରଣ ସେମାନେ ଅଲ୍ଲାହ ଏବଂ ତାଙ୍କ ରସୂଲଙ୍କର ବିରୋଧ କରିଥିଲେ; ଏବଂ ଯେ ଅଲ୍ଲାହଙ୍କର ବିରୋଧ କରେ। (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- ଯେଉଁ ଦିନ ସେ ସେମାନଙ୍କୁ ଡାକିବେ ଏବଂ କହିବେ: ମୋର ସେହି ଅଂଶୀଦାରମାନେ କେଉଁଠାରେ, ଯାହାଙ୍କ ବିଷୟରେ ତମେ ଦାବୀ କରୁଥିଲ? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ସେମାନେ କ'ଣ ଦେଖିନାହାନ୍ତି ଯେ ଅଲ୍ଲାହ, ଯିଏ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀ ସୃଷ୍ଟି କରିଛନ୍ତି, ସେ ସେମାନଙ୍କ ପରି ସୃଷ୍ଟି କରିବାକୁ ସକ୍ଷମ? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (ସେ) ଯିଏ ତମମାନଙ୍କୁ ମାଟିରୁ, ତା'ପରେ ବୀର୍ଯ୍ୟରୁ, ତା'ପରେ। (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- ସେମାନେ କହିଥାନ୍ତେ: ହେ ଆମ ପ୍ରଭୁ! ତୁମେ ଆମ ପାଖକୁ ଜଣେ ରସୂଲ କାହିଁକି ପଠାଇଲ ନାହିଁ, ତେବେ ଆମେ ତୁମ ନିଦର୍ଶନଗୁଡ଼ିକର ଅନୁସରଣ କରିଥାନ୍ତୁ? (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ତା'ପରେ ସେମାନଙ୍କର ପ୍ରତ୍ୟାବର୍ତ୍ତନ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କ ପାଖକୁ, ତା'ପରେ ସେ ସେମାନଙ୍କୁ ସେମାନଙ୍କ କର୍ମ ବିଷୟରେ ଜଣାଇବେ। (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- ସେମାନଙ୍କର ସେ ବିଷୟରେ କୌଣସି ଜ୍ଞାନ ନାହିଁ; ସେମାନେ କେବଳ ଅନୁମାନର ଅନୁସରଣ କରନ୍ତି। (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- ଆମେ ଆମ ପିତୃପୁରୁଷମାନଙ୍କୁ ଏକ ଧର୍ମ ଉପରେ ପାଇଲୁ, ଏବଂ ଆମେ ସେମାନଙ୍କ ପଦଚିହ୍ନ ଅନୁସରଣ କରୁଛୁ। (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- ଯେଉଁମାନଙ୍କୁ କିତାବ ଦିଆଯାଇଥିଲା, ସେମାନେ ସେମାନଙ୍କ ନିକଟରେ ଜ୍ଞାନ ଆସିବା ପରେ ହିଁ (ମତଭେଦ କଲେ)। (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- ଯେତେବେଳେ ଇବ୍ରାହିମ କହିଲେ: ହେ ମୋ ପ୍ରଭୁ! ଏହି ସହରକୁ ସୁରକ୍ଷିତ କର। (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- ସେ ତମମାନଙ୍କୁ କର୍ଣ୍ଣ, ଚକ୍ଷୁ ଏବଂ ହୃଦୟ ଦେଇଛନ୍ତି; ତମେ ଅଳ୍ପ କୃତଜ୍ଞତା ପ୍ରକାଶ କର। (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- ଯେଉଁମାନେ ଅଲ୍ଲାହଙ୍କ ନିଦର୍ଶନ ସମ୍ପର୍କରେ କୌଣସି ପ୍ରମାଣ ବିନା ବିତର୍କ କରନ୍ତି। (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- ତେଣୁ ଇବ୍ରାହିମଙ୍କ ଏକେଶ୍ୱରବାଦୀ ଧର୍ମର ଅନୁସରଣ କର, ସେ ମୁଶରିକମାନଙ୍କ ମଧ୍ୟରୁ ନ ଥିଲେ। (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- ଯେତେବେଳେ ଆମେ ତମମାନଙ୍କୁ ଫିରଔନର ଲୋକମାନଙ୍କଠାରୁ ଉଦ୍ଧାର କଲୁ, ଯେଉଁମାନେ ତମମାନଙ୍କୁ କଠୋର ଶିକ୍ଷା ଦେଉଥିଲେ। (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- ଏହା ହିଁ ସଳଖ ଧର୍ମ, କିନ୍ତୁ ଅଧିକାଂଶ ଲୋକ ଜାଣନ୍ତି ନାହିଁ। (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- ତୁମେ କ'ଣ ଦେଖୁନାହଁ ଯେ ଅଲ୍ଲାହ ତମମାନଙ୍କ ପାଇଁ ଆକାଶମଣ୍ଡଳରେ ଯାହା ଅଛି, ତାହା ବଶୀଭୂତ କରିଦେଇଛନ୍ତି? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- କାଫିରମାନେ କହିଥାନ୍ତେ: ଏହା ତ ସ୍ପଷ୍ଟ ଯାଦୁ। (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- ଯେତେବେଳେ ସେମାନଙ୍କ ନିକଟରେ ଆମର ସ୍ପଷ୍ଟ ଆୟତଗୁଡ଼ିକ ପାଠ କରି ଶୁଣାଯାଏ, ସେତେବେଳେ କାଫିରମାନେ କହନ୍ତି। (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- ଚିରସ୍ଥାୟୀ ସ୍ୱର୍ଗବଗିଚାଗୁଡ଼ିକ, ଯାହାର ତଳଦେଇ ନଦୀମାନେ ପ୍ରବାହିତ, ସେଠାରେ ସେମାନେ ଚିରଦିନ ରହିବେ। (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- ସେ ଯାହା ଇଚ୍ଛା କରନ୍ତି, ସୃଷ୍ଟି କରନ୍ତି; ନିଶ୍ଚୟ ଅଲ୍ଲାହ ସମସ୍ତ ଜିନିଷ ଉପରେ ସକ୍ଷମ। (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- ଯାହାଫଳରେ ସେ ତମମାନଙ୍କର ପାପ କ୍ଷମା କରିବେ ଏବଂ ତମମାନଙ୍କୁ ନିର୍ଦ୍ଧାରିତ ସମୟ ପର୍ଯ୍ୟନ୍ତ ଅବକାଶ ଦେବେ। (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- କ'ଣ ତମେ ଆମକୁ ଆମ ପିତୃପୁରୁଷମାନଙ୍କ ଉପାସନାରୁ ରୋକିବାକୁ ଚାହୁଁଛ? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- ଯେତେବେଳେ ତୁମ ପ୍ରଭୁ ଫେରିଶ୍ତାମାନଙ୍କୁ କହିଲେ: ମୁଁ ମାଟିରୁ ଜଣେ ମନୁଷ୍ୟ ସୃଷ୍ଟି କରୁଛି। (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- ସେ ହିଁ ନିଜ ଦୟା ଆଗରେ ପବନଗୁଡ଼ିକୁ ଶୁଭ ସମ୍ବାଦବାହକ ରୂପେ ପଠାନ୍ତି। (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- କୁହ: ପୃଥିବୀରେ ଭ୍ରମଣ କର ଏବଂ ଦେଖ ଯେ ପରିଣାମ କିପରି ହୋଇଥିଲା। (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀର ସୃଷ୍ଟିରେ, ଏବଂ ରାତ୍ରି ଓ ଦିନର ପରିବର୍ତ୍ତନରେ (ନିଦର୍ଶନ ଅଛି)। (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- ସେହି ବ୍ୟକ୍ତି କିଏ, ଯେ ଅଲ୍ଲାହଙ୍କୁ ଉତ୍ତମ ଋଣ ଦେବ, ଯାହାଫଳରେ ସେ ତାହାକୁ ଅନେକ ଗୁଣା ବଢ଼ାଇ ଦେବେ? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ତେଣୁ ସେମାନଙ୍କ ମଧ୍ୟରେ ଅଲ୍ଲାହଙ୍କ ଅବତୀର୍ଣ୍ଣ କରାଯାଇଥିବା (ବିଧାନ) ଅନୁସାରେ ବିଚାର କର, ଏବଂ ସେମାନଙ୍କ ଇଚ୍ଛାର ଅନୁସରଣ କରନାହିଁ। (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- ସେମାନେ ଫେରିଶ୍ତାମାନେ ସେମାନଙ୍କ ନିକଟକୁ ଆସିବା, କିମ୍ବା ତୁମ ପ୍ରଭୁଙ୍କ ଆଦେଶ ଆସିବା ବ୍ୟତୀତ ଅନ୍ୟ କିଛି ଅପେକ୍ଷା କରୁଛନ୍ତି କି? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- ଯେଉଁମାନେ ଅଲ୍ଲାହଙ୍କ ଉପରେ ମିଥ୍ୟା ଆରୋପ ଲଗାନ୍ତି, ସେମାନେ ସଫଳ ହେବେ ନାହିଁ। (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ଫିରଔନର ଲୋକମାନେ ଏବଂ ସେମାନଙ୍କ ପୂର୍ବବର୍ତ୍ତୀମାନଙ୍କ ପରି, ସେମାନେ ଆମର ନିଦର୍ଶନଗୁଡ଼ିକୁ ମିଥ୍ୟା ପ୍ରତିପାଦନ କଲେ। (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- ସେ ଈମାନଦାର ଏବଂ ସତ୍କର୍ମଶୀଳମାନଙ୍କୁ ଶୁଭ ସମ୍ବାଦ ଦିଅନ୍ତି ଯେ ସେମାନଙ୍କ ପାଇଁ ପୁରସ୍କାର ଅଛି। (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- ଅଲ୍ଲାହ ଆପଣା ବନ୍ଦାମାନଙ୍କ ମଧ୍ୟରୁ ଯାହାକୁ ଇଚ୍ଛା କରନ୍ତି, ଜୀବିକା ପ୍ରଶସ୍ତ କରିଦିଅନ୍ତି ଏବଂ ସଂକୁଚିତ ମଧ୍ୟ କରିଦିଅନ୍ତି। (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- ଏବଂ ତମେ ଗୁପ୍ତ ଓ ପ୍ରକାଶ୍ୟର ଜ୍ଞାତାଙ୍କ ନିକଟକୁ ପ୍ରତ୍ୟାବର୍ତ୍ତିତ ହେବ, ତା'ପରେ ସେ ତମମାନଙ୍କୁ ତମମାନଙ୍କ କର୍ମ ବିଷୟରେ ଜଣାଇବେ। (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- ଏବଂ ରକ୍ତ ସମ୍ପର୍କୀୟମାନେ, ଅଲ୍ଲାହଙ୍କ କିତାବରେ ପରସ୍ପର ପ୍ରତି ଅଧିକ ଘନିଷ୍ଠ। (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — ଫର୍ଜ / ୱାଜିବ (କରିବା ଆବଶ୍ୟକ; ଛାଡ଼ିଦେଲେ ପାପ)
- mustahabb / mandub (مستحب / مندوب) — ମୁସ୍ତାହବ / ମନ୍ଦୁବ (ସୁପାରିଶ କରାଯାଇଥାଏ; କଲେ ସବାବ, ନ କଲେ ପାପ ନାହିଁ)
- mubah (مباح) — ମୁବାହ / ଅନୁମତିପ୍ରାପ୍ତ (ତଟସ୍ଥ; ନ ସବାବ, ନ ପାପ)
- makruh (مكروه) — ମକରୁହ (ଅପ୍ରିୟ / ନିରୁତ୍ସାହିତ, କିନ୍ତୁ କଲେ ପାପ ନାହିଁ)
- haram (حرام) — ହରାମ (ନିଷିଦ୍ଧ; କରିବା ପାପ)
- halal (حلال, ଅନୁମତିପ୍ରାପ୍ତ / ବୈଧ) — ମୁବାହ ଓ ମୁସ୍ତାହବ ଉଭୟକୁ ଅନ୍ତର୍ଭୁକ୍ତ କରେ — ହରାମ ନୁହେଁ ତାହା ସବୁ
- କେବଳ ଅଲ୍ଲାହଙ୍କୁ ଉପାସନା କର ଏବଂ ତାଙ୍କ ସହାୟତା/ସହଯୋଗ ଲୋଡ଼। 1:5
- କେବଳ ଅଲ୍ଲାହଙ୍କୁ ଉପାସନା କର। 2:21
- ଅଲ୍ଲାହଙ୍କ ସହିତ ଅଂଶୀଦାର କର ନାହିଁ। 2:22
- ଅଲ୍ଲାହ କ୍ଷମାଶୀଳ (ତୌବା ଗ୍ରହଣକାରୀ), ସେ ଆଦମ (ଆଲୈହିସ୍ସଲାମ) ଙ୍କ ତୌବା ଗ୍ରହଣ କଲେ। 2:37
- ସତ୍ୟକୁ ଅସତ୍ୟ ସହିତ ମିଶ୍ରଣ କର ନାହିଁ ଏବଂ ସତ୍ୟକୁ ଲୁଚାଅ ନାହିଁ। 2:42
- ସଲାତ (ଦୈନିକ ପ୍ରାର୍ଥନା) ପ୍ରତିଷ୍ଠା କର ଏବଂ ଯାକାତ (ଦାନ) ଦିଅ। 2:43
- ନିଜେ ଅଭ୍ୟାସ କରିବା ପରେ ହିଁ ଅନ୍ୟମାନଙ୍କୁ ସତ୍କର୍ମର ଆଦେଶ ଦିଅ। 2:44
- ସବୁ କାର୍ଯ୍ୟରେ ଅଲ୍ଲାହଙ୍କ ସହାୟତା ଲୋଡ଼। 2:45
- ଦୁର୍ନୀତିରେ ଲିପ୍ତ ହୁଅ ନାହିଁ ଏବଂ ତାହା ବ୍ୟାପ୍ତ କର ନାହିଁ। 2:60
- ଲୋକମାନଙ୍କୁ ଉପାସନା ସ୍ଥଳକୁ ଯିବାରୁ ବାରଣ କର ନାହିଁ। 2:114
- ମସଜିଦର ପବିତ୍ରତାକୁ ସମ୍ମାନ କର। ତୁମ୍ଭର ପ୍ରାର୍ଥନା ସ୍ଥାନଗୁଡ଼ିକୁ ପରିଷ୍କାର ଓ ପବିତ୍ର ରଖ। 2:125
- ଅଲ୍ଲାହଙ୍କୁ ସ୍ମରଣ କର (ପ୍ରାର୍ଥନା, ତସବୀହ ଇତ୍ୟାଦି ଦ୍ୱାରା) ଏବଂ ସେ ତୁମ୍ଭକୁ ସ୍ମରଣ କରିବେ, ଏବଂ ତାଙ୍କ ପ୍ରତି କୃତଜ୍ଞ ରୁହ। 2:152
- ଦୁଃଖ-ଦୁର୍ଦ୍ଦଶାରେ ଧୈର୍ଯ୍ୟ ଧାରଣ କର। 2:153
- ଶୟତାନର ପଦକ୍ଷେପ ଅନୁସରଣ କର ନାହିଁ, ଯେ ଖୋଲା ଶତ୍ରୁ। 2:168
- କାହାରିକୁ ଅନ୍ଧ ଭାବରେ ଅନୁସରଣ କର ନାହିଁ। 2:170
- ସବୁ ଆମାନତ ରକ୍ଷା କର ଏବଂ ପୂରଣ କର। ନିଜର ଧାର୍ମିକ କର୍ତ୍ତବ୍ୟଗୁଡ଼ିକ ଆନ୍ତରିକତାର ସହିତ ପାଳନ କର। ନିଜର ଶପଥ ଓ ପ୍ରତିଜ୍ଞାଗୁଡ଼ିକ ପୂରଣ କର। ପ୍ରତିଶ୍ରୁତି ରକ୍ଷା କର, ବିଶେଷ କରି ଅଲ୍ଲାହଙ୍କୁ ଦିଆଯାଇଥିବା ପ୍ରତିଶ୍ରୁତି। ଆବଶ୍ୟକତାମାନଙ୍କୁ ସହାୟତା କର ଏବଂ କଷ୍ଟ ଦୂର କର। ଦୈବୀ କୃପା ହରାଇବା ପାପଗୁଡ଼ିକୁ ପରିହାର କର। ଅହଙ୍କାର ତୁମ୍ଭକୁ ଅନ୍ୟାୟ ଆଡ଼କୁ ନ ନେଉ। 2:177
- କିସାସ୍ (ଦଣ୍ଡରେ ସମାନତା ନିୟମ) ରେ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ଜୀବନ ଅଛି। 2:179
- ରମଜାନ୍ ମାସରେ ରୋଜା ରଖ। ମୁତ୍ତାକୀ (ଧର୍ମପରାୟଣ) ହେବା ପାଇଁ ନିର୍ଦ୍ଧାରିତ ରୋଜା ପାଳନ କର। 2:183
- କୁରଆନ୍କୁ ଅନ୍ତିମ ମାର୍ଗଦର୍ଶକ ଭାବରେ ସମ୍ମାନ କର। 2:185
- ପରସ୍ପରର ସମ୍ପତ୍ତି ଅନ୍ୟାୟରେ ଖାଅ ନାହିଁ, ଏବଂ ବିଚାରପତିମାନଙ୍କୁ (ତୁମ୍ଭମାନଙ୍କର ମାମଲା ଦାଖଲ କରିବା ପୂର୍ବରୁ) ଘୁଷ ଦିଅ ନାହିଁ। 2:188
- ଅନ୍ୟମାନଙ୍କୁ ଶବ୍ଦ ବା କାର୍ଯ୍ୟରେ ଅତ୍ୟାଚାର କର ନାହିଁ। କେବେ ବି ଆକ୍ରମଣକାରୀ ଭାବରେ ଯୁଦ୍ଧ କର ନାହିଁ, କେବଳ ପ୍ରତିରକ୍ଷା ପାଇଁ। 2:190
- ଅନାଥମାନଙ୍କୁ ସୁରକ୍ଷା ଦିଅ। ଅନାଥମାନଙ୍କ ସମ୍ପତ୍ତିରେ ସଚ୍ଚୋଟ ଭାବରେ କାର୍ଯ୍ୟ କର ଏବଂ ସେମାନଙ୍କ ସମ୍ପତ୍ତି ଖାଅ ନାହିଁ। 2:220
- ତୌବା କର ଏବଂ ଅଲ୍ଲାହଙ୍କ କ୍ଷମା ପ୍ରାର୍ଥନା କର। ଋତୁସ୍ରାବ ସମୟରେ ଯୌନ ସମ୍ପର୍କ ରଖ ନାହିଁ। ପବିତ୍ରତା (ଶାରୀରିକ ଓ ଆଧ୍ୟାତ୍ମିକ) ବଜାୟ ରଖ। 2:222
- ନିଜ ପରିବାର ପ୍ରତି ନିଜର ଦାୟିତ୍ୱ ପୂରଣ କର। 2:233
- ନେତାମାନଙ୍କୁ ସେମାନଙ୍କ ଯୋଗ୍ୟତା ଆଧାରରେ ମନୋନୀତ କର। 2:247
- ଧର୍ମରେ ବାଧ୍ୟତା ନାହିଁ। 2:256
- ସମ୍ପତ୍ତି ଦାନରେ ଖର୍ଚ୍ଚ କର। ସମ୍ପତ୍ତି ଓ ସମୟ ଉଭୟରେ ଦାନୀ ହୁଅ। 2:261
- ନିଜର ଉଦାରତାକୁ ଗର୍ବ କରି ଦାନକୁ ବ୍ୟର୍ଥ କର ନାହିଁ। 2:264
- ଶୟତାନ ତୁମ୍ଭକୁ ଦାରିଦ୍ର୍ୟର ଭୟ ଦେଖାଏ ଏବଂ ଅଶ୍ଳୀଳ କାର୍ଯ୍ୟ (ଫାହ୍ଶା — ଖରାପ କର୍ମ, ଅବୈଧ ଯୌନ ସମ୍ପର୍କ, ପାପ) କରିବାକୁ ଆଦେଶ ଦିଏ। 2:268
- ଆବଶ୍ୟକତାମାନଙ୍କୁ ଖୋଜ ଏବଂ ସେମାନଙ୍କୁ ସାହାଯ୍ୟ କର। 2:273
- ସୁଦ ଓ ବ୍ୟାଜରେ ଲିପ୍ତ ହୁଅ ନାହିଁ। ସୁଦଯୁକ୍ତ ସମ୍ପତ୍ତି ଖାଅ ନାହିଁ। ରିବା (ସୁଦ) ଖାଅ ନାହିଁ। 2:275
- ଋଣୀ କଷ୍ଟରେ ଥିଲେ ପରିଶୋଧ ପାଇଁ ଅଧିକ ସମୟ ଦିଅ। 2:280
- ବ୍ୟବସାୟିକ ଲେନଦେନରେ ନିଜ ପ୍ରତିଜ୍ଞା ପାଳନ କର। ଆର୍ଥିକ ବ୍ୟାପାରରେ ସତ୍ୟବାଦୀ ହୁଅ। ସବୁ ପ୍ରତିବଦ୍ଧତାରେ ସଚ୍ଚୋଟ ଭାବରେ କାର୍ଯ୍ୟ କର। ନିର୍ଦ୍ଧାରିତ ସମୟ ପାଇଁ ଋଣ ଚୁକ୍ତି କଲେ ତାହା ଲେଖ। ବ୍ୟବସାୟିକ ଚୁକ୍ତି କଲାବେଳେ ସାକ୍ଷୀ ରଖ। 2:282
- ସବୁ ଆମାନତ ରକ୍ଷା କର ଏବଂ ପୂରଣ କର। 2:283
- ଅବତୀର୍ଣ୍ଣ ଗ୍ରନ୍ଥଗୁଡ଼ିକ ଓ ସବୁ ପୟଗମ୍ବରଙ୍କୁ ବିଶ୍ୱାସ କର। 2:285
- ଅଲ୍ଲାହ କାହାକୁ ବି ତା'ର କ୍ଷମତା ଠାରୁ ଅଧିକ ବୋଝ ଦିଅନ୍ତି ନାହିଁ। ସେ ଭଲ କର୍ମର ପୁରସ୍କାର ପାଏ ଏବଂ ଖରାପ କର୍ମର ଦଣ୍ଡ ପାଏ। ଈଶ୍ବର ମନୁଷ୍ୟକୁ ତା'ର କ୍ଷମତା ଠାରୁ ଅଧିକ ବୋଝ ଦିଅନ୍ତି ନାହିଁ; ଆମେ ବି ତାହା କରିବା ଉଚିତ ନୁହେଁ। କଷ୍ଟରେ ମଧ୍ୟ ଅଲ୍ଲାହଙ୍କ ଯୋଜନା ଉପରେ ବିଶ୍ୱାସ ରଖ। 2:286
- ଯେ ପ୍ରତିଜ୍ଞା ପୂରଣ କରେ ଏବଂ ଅଲ୍ଲାହଙ୍କୁ ଡରେ, ତେବେ ଅଲ୍ଲାହ ଧର୍ମପରାୟଣମାନଙ୍କୁ ଭଲ ପାଆନ୍ତି। 3:76
- ସାମର୍ଥ୍ୟ ଥିଲେ ହଜ୍ (ତୀର୍ଥଯାତ୍ରା) କର। 3:97
- ବିଭକ୍ତ ହୁଅ ନାହିଁ। 3:103
- ସତ୍କର୍ମର ଆଦେଶ ଦିଅ ଏବଂ ଦୁଷ୍କର୍ମରୁ ନିବୃତ୍ତ କର। ନିଜ ସମାଜରେ ନ୍ୟାୟକୁ ଉତ୍ସାହିତ କର। ଅନ୍ୟମାନଙ୍କୁ ଅଲ୍ଲାହଙ୍କ ସ୍ମରଣ ଆଡ଼କୁ ଡାକ। 3:104
- ବିଶ୍ୱାସୀମାନେ ଅଲ୍ଲାହଙ୍କ ଉପରେ ହିଁ ଭରସା କରିବା ଉଚିତ। 3:122
- ରିବା (ସୁଦ) ଖାଅ ନାହିଁ। 3:130
- ଦୟା ପାଇବା ପାଇଁ ଅଲ୍ଲାହ ଓ ତାଙ୍କ ରସୂଲଙ୍କ ଆଜ୍ଞା ପାଳନ କର। 3:132
- ଅଲ୍ଲାହ (ଅଲ୍ଲାହଙ୍କ ମାର୍ଗରେ — ଦାନ, ଧର୍ମଦାନ ଇତ୍ୟାଦି) ସମୃଦ୍ଧି ଓ ଅଭାବ ଉଭୟରେ ଖର୍ଚ୍ଚ କରୁଥିବା ଲୋକମାନଙ୍କୁ, କ୍ରୋଧକୁ ଦମନ କରୁଥିବା ଲୋକମାନଙ୍କୁ ଏବଂ ଲୋକମାନଙ୍କୁ କ୍ଷମା କରୁଥିବା ଲୋକମାନଙ୍କୁ ଭଲ ପାଆନ୍ତି। 3:134
- କ୍ରୋଧ ଦମନ କର। ନିଜର କ୍ରୋଧକୁ ନିୟନ୍ତ୍ରଣ କର। 3:134
- ଅନ୍ୟମାନଙ୍କ ଭୁଲକୁ କ୍ଷମା କର ଏବଂ ମାଫ କର। 3:135
- କଥାରେ କଠୋର ହୁଅ ନାହିଁ। ଯେଉଁମାନେ ତୁମଠାରୁ ଭିନ୍ନ, ସେମାନଙ୍କ ପ୍ରତି ଧୈର୍ଯ୍ୟ ରଖ। 3:159
- ଯଦି ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କୁ ସାହାଯ୍ୟ କରନ୍ତି, ତେବେ କେହି ତୁମ୍ଭମାନଙ୍କୁ ପରାସ୍ତ କରିପାରିବେ ନାହିଁ; ଏବଂ ଯଦି ସେ ତୁମ୍ଭମାନଙ୍କୁ ପରିତ୍ୟାଗ କରନ୍ତି, ତେବେ ତାଙ୍କ ପରେ କିଏ ତୁମ୍ଭମାନଙ୍କୁ ସାହାଯ୍ୟ କରିପାରିବ? 3:160
- ପ୍ରତ୍ୟେକେ ମୃତ୍ୟୁର ସ୍ୱାଦ ଚାଖିବେ। ଏବଂ କେବଳ ପୁନରୁତ୍ଥାନ ଦିନରେ ତୁମ୍ଭମାନଙ୍କୁ ତୁମ୍ଭମାନଙ୍କର ସମ୍ପୂର୍ଣ୍ଣ ପୁରସ୍କାର ଦିଆଯିବ। 3:185
- ପ୍ରକୃତିର ଆଶ୍ଚର୍ଯ୍ୟ ଏବଂ ଏହି ବ୍ରହ୍ମାଣ୍ଡର ସୃଷ୍ଟି ସମ୍ବନ୍ଧରେ ଗଭୀର ଭାବରେ ଚିନ୍ତା କର। ଜାଣ ଯେ ଈଶ୍ବର ଏହି ବ୍ରହ୍ମାଣ୍ଡକୁ ଅର୍ଥ ଏବଂ ଉଦ୍ଦେଶ୍ୟ ସହିତ ସୃଷ୍ଟି କରିଛନ୍ତି। 3:191
- ପୁରୁଷ ଓ ସ୍ତ୍ରୀ ସେମାନଙ୍କ କର୍ମ ପାଇଁ ସମାନ ପୁରସ୍କାର ପାଆନ୍ତି। 3:195
- ଯେଉଁମାନେ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କୁ ଡରନ୍ତି, ସେମାନଙ୍କ ପାଇଁ (ସ୍ୱର୍ଗରେ) ବଗିଚା ଅଛି, ଯାହାର ତଳେ ନଦୀ ପ୍ରବାହିତ; ସେଠାରେ ସେମାନେ ସଦାକାଳ ରହିବେ, ଅଲ୍ଲାହଙ୍କ ତରଫରୁ ଆତିଥ୍ୟ ଭାବରେ। 3:198
- ସବୁ କର୍ମରେ ସଦା ଅଲ୍ଲାହଙ୍କ ସନ୍ତୁଷ୍ଟି ପାଇଁ ଚେଷ୍ଟା କର। 3:200
- ନିଜ ପ୍ରଭୁଙ୍କୁ ଡର, ତାଙ୍କୁ ଭୟ କର ଏବଂ (ସମ୍ପର୍କୀୟ) ସମ୍ପର୍କ ଛିନ୍ନ କର ନାହିଁ। 4:1
- ଅନାଥମାନଙ୍କୁ ସେମାନଙ୍କ ସମ୍ପତ୍ତି ଦିଅ ଏବଂ (ନିଜର ଖରାପ) ସେମାନଙ୍କ (ଭଲ) ସହିତ ବଦଳାଅ ନାହିଁ; ଏବଂ ସେମାନଙ୍କ ସମ୍ପତ୍ତି (ନିଜ ସମ୍ପତ୍ତିରେ ମିଶାଇ) ଖାଅ ନାହିଁ। 4:2
- ଯେଉଁ ସ୍ତ୍ରୀମାନଙ୍କୁ ବିବାହ କର, ସେମାନଙ୍କୁ ସେମାନଙ୍କ ମହର (ବିବାହ ସମୟରେ ସ୍ୱାମୀ ପତ୍ନୀଙ୍କୁ ଦେବା ଆବଶ୍ୟକ ଉପହାର) ଖୁସି ମନରେ ଦିଅ। 4:4
- ଅନାଥମାନଙ୍କ ଅଧିକାର ସୁରକ୍ଷା କର। 4:6
- ମୃତକର ସମ୍ପତ୍ତି ତା'ର ପରିବାର ସଦସ୍ୟମାନଙ୍କ ମଧ୍ୟରେ ବାଣ୍ଟି ଦିଆଯିବା ଉଚିତ। ସ୍ତ୍ରୀମାନଙ୍କର ଉତ୍ତରାଧିକାର ଅଧିକାର ଅଛି। 4:7
- ଅନାଥମାନଙ୍କ ସମ୍ପତ୍ତି ଅନ୍ୟାୟରେ ଖାଅ ନାହିଁ। 4:10
- ଉତ୍ତରାଧିକାର ସମ୍ବନ୍ଧୀୟ ଆଦେଶଗୁଡ଼ିକୁ ପାଳନ କର। 4:11
- ସ୍ତ୍ରୀମାନଙ୍କୁ ସେମାନଙ୍କ ଇଚ୍ଛା ବିରୁଦ୍ଧରେ ଉତ୍ତରାଧିକାରୀ କରିବା ନିଷିଦ୍ଧ, ଏବଂ ସେମାନଙ୍କ ସହିତ କଠୋର ବ୍ୟବହାର କର ନାହିଁ। ସେମାନଙ୍କ (ପତ୍ନୀମାନଙ୍କ) ସହିତ ସମ୍ମାନଜନକ ଭାବରେ ବାସ କର। ସ୍ତ୍ରୀମାନଙ୍କ ଅଧିକାରକୁ ସମ୍ମାନ କର ଏବଂ ରକ୍ଷା କର। ନିଜ ସ୍ତ୍ରୀ ସହିତ ଦୟା ଓ କରୁଣାର ବ୍ୟବହାର କର। ସ୍ତ୍ରୀମାନଙ୍କ ସହିତ ସମ୍ମାନ ଓ ନ୍ୟାୟର ବ୍ୟବହାର କର। 4:19
- ନିଜ ରକ୍ତ ସମ୍ପର୍କୀୟମାନଙ୍କୁ ବିବାହ କର ନାହିଁ। 4:23
- ପରସ୍ପରକୁ (କିମ୍ବା ନିଜକୁ) ହତ୍ୟା କର ନାହିଁ। ନିଶ୍ଚିତ ଭାବରେ ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କ ପ୍ରତି ଦୟାଳୁ। ପରସ୍ପରର ସମ୍ପତ୍ତି ଅନ୍ୟାୟରେ ଖାଅ ନାହିଁ। 4:29
- ଯଦି ତୁମ୍ଭମାନେ ନିଷିଦ୍ଧ ବଡ଼ ପାପଗୁଡ଼ିକୁ ପରିହାର କର, ତେବେ ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କ (ଛୋଟ) ପାପଗୁଡ଼ିକୁ କ୍ଷମା କରିବେ ଏବଂ ତୁମ୍ଭମାନଙ୍କୁ ସମ୍ମାନଜନକ ପ୍ରବେଶ (ସ୍ୱର୍ଗ) ରେ ପ୍ରବେଶ କରାଇବେ। 4:31
- ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କ ମଧ୍ୟରୁ କେହି କାହାଠାରୁ ଅଧିକ ଯାହା ଦେଇଛନ୍ତି, ତାହାର ଇଚ୍ଛା କର ନାହିଁ। ଈର୍ଷା ଓ ହିଂସାରୁ ଦୂରେଇ ରୁହ। 4:32
- ପୁରୁଷମାନେ ସ୍ତ୍ରୀମାନଙ୍କ ରକ୍ଷକ ଓ ପରିଚାଳକ, କାରଣ ଅଲ୍ଲାହ ସେମାନଙ୍କ ମଧ୍ୟରୁ କେହି କାହାଠାରୁ ଅଧିକ ଶ୍ରେଷ୍ଠ କରିଛନ୍ତି, ଏବଂ କାରଣ ସେମାନେ ସେମାନଙ୍କ ସମ୍ପତ୍ତିରୁ (ସେମାନଙ୍କ ପାଳନ ପାଇଁ) ଖର୍ଚ୍ଚ କରନ୍ତି। ପୁରୁଷ ପରିବାରର ରକ୍ଷକ ଓ ସହାୟକ। 4:34
- ଅଲ୍ଲାହଙ୍କୁ ଉପାସନା କର ଏବଂ ତାଙ୍କ ସହିତ କାହାକୁ ବି ଅଂଶୀଦାର କର ନାହିଁ, ପିତାମାତା, ସମ୍ପର୍କୀୟ, ଅନାଥ, ଦରିଦ୍ର, ପଡ଼ୋଶୀ, ସଙ୍ଗୀ, ପଥିକ (ଯାହାକୁ ଭେଟ), ଏବଂ ନିଜ ଡାହାଣ ହାତ ଅଧିକାରରେ ଥିବା (ଦାସ) ମାନଙ୍କ ସହିତ ସଦ୍ୟବହାର କର। ଅଲ୍ଲାହ ଅହଙ୍କାରୀ ଓ ଗର୍ବିତମାନଙ୍କୁ ପସନ୍ଦ କରନ୍ତି ନାହିଁ। ଅନ୍ୟମାନଙ୍କ ସହିତ ଭଲ ବ୍ୟବହାର କର। ଦୁର୍ବଳମାନଙ୍କ ପ୍ରତି ଦୟା ଦେଖାଅ। ପାରିବାରିକ ସମ୍ପର୍କ ବଜାୟ ରଖ ଏବଂ ସମ୍ପର୍କୀୟମାନଙ୍କୁ ସମ୍ମାନ କର। 4:36
- କୃପଣ ହୁଅ ନାହିଁ। 4:37
- ଅଲ୍ଲାହ ତାଙ୍କ ସହିତ ଅଂଶୀଦାର କରିବାକୁ କ୍ଷମା କରନ୍ତି ନାହିଁ, କିନ୍ତୁ ଏହା ବ୍ୟତୀତ ଯାହାକୁ ଇଚ୍ଛା କ୍ଷମା କରନ୍ତି। 4:48
- ଅନ୍ୟମାନଙ୍କ ପ୍ରତି ଈର୍ଷା କର ନାହିଁ। 4:54
- ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କୁ ଆମାନତଗୁଡ଼ିକ ତାଙ୍କ ମାଲିକମାନଙ୍କୁ ଫେରାଇ ଦେବାକୁ ଆଦେଶ ଦିଅନ୍ତି। ଯେତେବେଳେ ତୁମ୍ଭମାନେ ଲୋକମାନଙ୍କ ମଧ୍ୟରେ ବିଚାର କର, ନ୍ୟାୟ ସହିତ ବିଚାର କର। 4:58
- ଅଲ୍ଲାହ ଓ ତାଙ୍କ ରସୂଲଙ୍କ ଆଜ୍ଞା ପାଳନ କର। ତୁମ୍ଭମାନଙ୍କ ମଧ୍ୟରେ କ୍ଷମତାଧାରୀମାନଙ୍କୁ ସମ୍ମାନ ଦିଅ। 4:59
- ଦୁର୍ବଳ ଓ ଅସହାୟମାନଙ୍କ ଉପରେ ଅତ୍ୟାଚାର କର ନାହିଁ। 4:75
- ତୁମ୍ଭମାନଙ୍କୁ ଯାହା ଭଲ ମିଳେ, ତାହା ଅଲ୍ଲାହଙ୍କ ତରଫରୁ; ଏବଂ ଯାହା ଖରାପ ଘଟେ, ତାହା ତୁମ୍ଭମାନଙ୍କ ନିଜ ତରଫରୁ। 4:79
- ଯେ ରସୂଲ (ମୁହମ୍ମଦ ﷺ) ଙ୍କ ଆଜ୍ଞା ପାଳନ କରେ, ସେ ଅଲ୍ଲାହଙ୍କ ଆଜ୍ଞା ପାଳନ କଲା। 4:80
- ଯେ ଭଲ କାର୍ଯ୍ୟର ସୁପାରିଶ କରେ, ସେ ତାହାର ପୁରସ୍କାର ପାଏ; ଏବଂ ଯେ ଖରାପ କାର୍ଯ୍ୟର ସୁପାରିଶ କରେ, ସେ ତାହାର ବୋଝ ବହନ କରେ। 4:85
- ଜଣେ ବିଶ୍ୱାସୀ ଆଉ ଜଣେ ବିଶ୍ୱାସୀଙ୍କୁ ହତ୍ୟା କରିବା ଉଚିତ ନୁହେଁ, କିନ୍ତୁ ଭୁଲରେ ହେଲେ ବ୍ୟତୀତ। 4:92
- ଯେ ଜାଣିଶୁଣି ଜଣେ ବିଶ୍ୱାସୀଙ୍କୁ ହତ୍ୟା କରେ, ତା'ର ଦଣ୍ଡ ଜାହନ୍ନମ, ଯେଉଁଠାରେ ସେ ସଦାକାଳ ରହିବ। ଅଲ୍ଲାହଙ୍କ କ୍ରୋଧ ଓ ଅଭିଶାପ ତା' ଉପରେ, ଏବଂ ତା' ପାଇଁ ବଡ଼ ଦଣ୍ଡ ପ୍ରସ୍ତୁତ କରାଯାଇଛି। 4:93
- ଯେ ଅଲ୍ଲାହଙ୍କ ମାର୍ଗରେ (ନିଜ ଘରୁ) ହିଜରତ କରେ, ସେ ପୃଥିବୀରେ ବହୁତ ଆଶ୍ରୟସ୍ଥଳ ଓ ପ୍ରାଚୁର୍ଯ୍ୟ ପାଇବ। 4:100
- ନିଜର ପ୍ରାର୍ଥନାଗୁଡ଼ିକ ସମୟାନୁବର୍ତ୍ତୀ କର। 4:103
- ଯେଉଁମାନେ ଆମାନତରେ ବିଶ୍ୱାସଘାତ କରନ୍ତି, ସେମାନଙ୍କୁ ସମର୍ଥନ କିମ୍ବା ଓକିଲ ହୁଅ ନାହିଁ। 4:105
- ଅଲ୍ଲାହଙ୍କ କ୍ଷମା ପ୍ରାର୍ଥନା କର, ନିଶ୍ଚିତ ଭାବରେ ଅଲ୍ଲାହ କ୍ଷମାଶୀଳ, ଦୟାବାନ। 4:106
- ହେ ବିଶ୍ୱାସୀମାନେ! ନ୍ୟାୟ ପାଇଁ ଦୃଢ଼ ଭାବରେ ଠିଆ ହୁଅ, ଅଲ୍ଲାହଙ୍କ ପାଇଁ ସାକ୍ଷୀ ହୁଅ, ଯଦିଓ ତାହା ନିଜ ବିରୁଦ୍ଧରେ, କିମ୍ବା ପିତାମାତା, କିମ୍ବା ସମ୍ପର୍କୀୟମାନଙ୍କ ବିରୁଦ୍ଧରେ, ସେ ଧନୀ ହେଉ କିମ୍ବା ଗରିବ। ନ୍ୟାୟରେ ବିଳମ୍ବ କର ନାହିଁ; ଭୁଲ ସୁଧାରିବା ପାଇଁ ତୁରନ୍ତ କାର୍ଯ୍ୟ କର। 4:135
- ମୁନାଫିକ୍ମାନେ ଅଲ୍ଲାହଙ୍କୁ ଠକିବାକୁ ଚାହାନ୍ତି, କିନ୍ତୁ ସେ ହିଁ ସେମାନଙ୍କୁ ଠକନ୍ତି। 4:142
- ମୁନାଫିକ୍ମାନେ ନର୍କର ସବୁଠାରୁ ତଳ ତଳରେ ରହିବେ; ଏବଂ ତୁମ୍ଭେ ସେମାନଙ୍କ ପାଇଁ କୌଣସି ସହାୟକ ପାଇବ ନାହିଁ। 4:145
- ଅଲ୍ଲାହ ପସନ୍ଦ କରନ୍ତି ନାହିଁ ଯେ ଖରାପ କଥା ସାର୍ବଜନୀନ ଭାବରେ କୁହାଯାଉ, କିନ୍ତୁ ଯାହା ଉପରେ ଅତ୍ୟାଚାର ହୋଇଛି, ତାହା ବ୍ୟତୀତ। 4:148
- ରସୂଲମାନଙ୍କୁ ସୁସମାଚାର ଦାତା ଏବଂ ସତର୍କକାରୀ ଭାବରେ ପଠାଯାଇଛି, ଯାହାଫଳରେ ରସୂଲମାନଙ୍କ (ଆଗମନ) ପରେ ଲୋକମାନଙ୍କର ଅଲ୍ଲାହ ବିରୁଦ୍ଧରେ କୌଣସି ବାହାନା ନ ରହେ। 4:165
- ନିଜର ପ୍ରତିଜ୍ଞା ଓ ଅଙ୍ଗୀକାର ପୂରଣ କର। 5:1
- ସତ୍କର୍ମ ଓ ଧର୍ମପରାୟଣତାରେ ପରସ୍ପରକୁ ସାହାଯ୍ୟ କର, ଏବଂ ପାପ ଓ ଶତ୍ରୁତାରେ ସାହାଯ୍ୟ କର ନାହିଁ। 5:2
- ମୃତ ଜନ୍ତୁ, ରକ୍ତ ଏବଂ ଘୁଷୁରି ମାଂସ ଖାଅ ନାହିଁ। 5:3
- ନ୍ୟାୟପରାୟଣ ହୁଅ, ଅନ୍ୟମାନଙ୍କ ପ୍ରତି ଶତ୍ରୁତା ଓ ଘୃଣା ତୁମ୍ଭମାନଙ୍କୁ ନ୍ୟାୟରୁ ଦୂରେଇ ନ ଦେଉ। ନ୍ୟାୟପରାୟଣ ହୁଅ। ଜାଣ ଯେ ନ୍ୟାୟପରାୟଣତା ଧର୍ମପରାୟଣତାର ନିକଟତର। ନ୍ୟାୟରେ ବିଳମ୍ବ କର ନାହିଁ; ଭୁଲ ସୁଧାରିବା ପାଇଁ ତୁରନ୍ତ କାର୍ଯ୍ୟ କର। 5:8
- ଅଲ୍ଲାହଙ୍କ ନିକଟତର ହେବାର ମାଧ୍ୟମ ଖୋଜ ଏବଂ ତାଙ୍କ ମାର୍ଗରେ ଯଥାସାଧ୍ୟ ଚେଷ୍ଟା କର। ଯାହାଫଳରେ ତୁମ୍ଭମାନେ ସଫଳ ହୁଅ। 5:35
- ନିଜର ଶପଥ ଓ ପ୍ରତିଜ୍ଞା ପୂରଣ କର। 5:89
- ମାଦକ ପାନୀୟ ଓ ମଦ୍ୟପାନରୁ ଦୂରେଇ ରୁହ। ମାଦକ ପାନୀୟ (ସବୁ ପ୍ରକାର ମଦ୍ୟ), ଜୁଆ, ଅଲ-ଅନସାବ (ପଥର ବେଦୀ) ଏବଂ ଅଲ-ଅଜଲାମ (ଭାଗ୍ୟ ବା ନିଷ୍ପତ୍ତି ପାଇଁ ତୀର) ଗୁଡ଼ିକୁ କଠୋର ଭାବରେ ପରିହାର କର, ଏଗୁଡ଼ିକ ଶୟତାନର କାର୍ଯ୍ୟର ଅପବିତ୍ରତା। 5:90
- ଯେତେବେଳେ ତୁମ୍ଭମାନେ ହଜ୍ କିମ୍ବା ଉମରା (ତୀର୍ଥଯାତ୍ରା) ପାଇଁ ଇହରାମ ଅବସ୍ଥାରେ ଥାଅ, ଶିକାର କର ନାହିଁ। 5:95
- ଯେଉଁ ବିଷୟଗୁଡ଼ିକ ଯଦି ତୁମ୍ଭମାନଙ୍କୁ ସ୍ପଷ୍ଟ କରାଯାଏ, ତେବେ ତୁମ୍ଭମାନଙ୍କୁ କଷ୍ଟ ଦେଇପାରେ, ସେଗୁଡ଼ିକ ବିଷୟରେ ପଚାର ନାହିଁ। 5:101
- ଅନ୍ୟମାନଙ୍କ ଦେବତାମାନଙ୍କୁ ଗାଳି ଦିଅ ନାହିଁ। ସେମାନେ (ଅବିଶ୍ୱାସୀମାନେ) ଅଲ୍ଲାହଙ୍କୁ ଛାଡ଼ି ଯାହାର ଉପାସନା କରନ୍ତି, ସେମାନଙ୍କୁ ଗାଳି ଦିଅ ନାହିଁ, ଅନ୍ୟଥା ସେମାନେ ଅଜ୍ଞତାବଶତଃ ଅଲ୍ଲାହଙ୍କୁ ଗାଳି ଦେବେ। 6:108
- ଯଦି ତୁମ୍ଭମାନେ ପୃଥିବୀରେ ଥିବା ବହୁସଂଖ୍ୟକଙ୍କ ଅନୁସରଣ କର, ତେବେ ସେମାନେ ତୁମ୍ଭମାନଙ୍କୁ ଅଲ୍ଲାହଙ୍କ ମାର୍ଗରୁ ବିଚ୍ୟୁତ କରିବେ। ସେମାନେ କେବଳ ଅନୁମାନର ଅନୁସରଣ କରନ୍ତି ଏବଂ ସେମାନେ କେବଳ ମିଥ୍ୟା କୁହନ୍ତି। 6:116
- (ମାନବମାନେ) ସବୁ ପ୍ରକାର ପାପ, ଖୋଲା ଓ ଲୁଚା, ପରିତ୍ୟାଗ କର। 6:120
- (ବିଶ୍ୱାସୀମାନେ) ଯେଉଁ (ମାଂସ) ଉପରେ ଅଲ୍ଲାହଙ୍କ ନାମ (ଜନ୍ତୁ ବଧ ସମୟରେ) ନିଆଯାଇ ନାହିଁ, ତାହା ଖାଅ ନାହିଁ। 6:121
- ଅଲ୍ଲାହ ଯାକୁ ପଥ ଦେଖାଇବାକୁ ଚାହାନ୍ତି, ତା'ର ଛାତି ଇସଲାମ ପାଇଁ ଖୋଲି ଦିଅନ୍ତି; ଏବଂ ଯାକୁ ପଥଭ୍ରଷ୍ଟ କରିବାକୁ ଚାହାନ୍ତି, ତା'ର ଛାତି ସଂକୀର୍ଣ୍ଣ ଓ ଚିପା ହୋଇଯାଏ। 6:125
- ଖର୍ଚ୍ଚରେ ସଂଯମୀ ହୁଅ ଏବଂ ଅପବ୍ୟୟରୁ ଦୂରେଇ ରୁହ। ସବୁ ସୃଷ୍ଟିର ଅଧିକାର ସୁରକ୍ଷା କର। 6:141
- ଅଲ୍ଲାହଙ୍କ ସହିତ ଅଂଶୀଦାର କର ନାହିଁ, ପିତାମାତାଙ୍କ ସହିତ ସଦ୍ୟବହାର କର, ଦାରିଦ୍ର୍ୟ ଭୟରେ ନିଜ ସନ୍ତାନମାନଙ୍କୁ ହତ୍ୟା କର ନାହିଁ, ଅଶ୍ଳୀଳ କାର୍ଯ୍ୟର ନିକଟକୁ ଯାଅ ନାହିଁ, ଅଲ୍ଲାହ ଯାହାକୁ ହତ୍ୟା କରିବାକୁ ନିଷିଦ୍ଧ କରିଛନ୍ତି, ତାକୁ ନ୍ୟାୟସଙ୍ଗତ କାରଣ ବିନା ହତ୍ୟା କର ନାହିଁ। 6:151
- ସଚ୍ଚୋଟ ହୁଅ; କୌଣସି ବ୍ୟବହାରରେ ପ୍ରତାରଣା କର ନାହିଁ। ଅନାଥର ସମ୍ପତ୍ତି ନିକଟକୁ ଯାଅ ନାହିଁ, କିନ୍ତୁ ତାହାକୁ ଉନ୍ନତ କରିବା ପାଇଁ, ନ୍ୟାୟ ସହିତ ପୂର୍ଣ୍ଣ ପରିମାଣ ଓ ପୂର୍ଣ୍ଣ ଓଜନ ଦିଅ, ଯେତେବେଳେ କହ, ସତ୍ୟ କହ, ଯଦିଓ ତାହା ନିକଟ ସମ୍ପର୍କୀୟଙ୍କ ବିଷୟରେ, ଏବଂ ଅଲ୍ଲାହଙ୍କ ପ୍ରତିଜ୍ଞା ପୂରଣ କର। 6:152
- ସିଧା ପଥ ଅନୁସରଣ କର ଏବଂ (ଅନ୍ୟ) ପଥଗୁଡ଼ିକ ଅନୁସରଣ କର ନାହିଁ, କାରଣ ସେଗୁଡ଼ିକ ତୁମ୍ଭମାନଙ୍କୁ ତାଙ୍କ ପଥରୁ ଅଲଗା କରିଦେବେ। 6:153
- (ମୁହମ୍ମଦ ﷺ) କୁହ: "ନିଶ୍ଚିତ ଭାବରେ, ମୋର ପ୍ରାର୍ଥନା, ମୋର କୁର୍ବାନୀ, ମୋର ଜୀବନ ଓ ମୋର ମୃତ୍ୟୁ ସବୁ ବିଶ୍ୱର ପାଳନକାର୍ତ୍ତା ଅଲ୍ଲାହଙ୍କ ପାଇଁ।" 6:162
- ଅହଙ୍କାରୀ ହୁଅ ନାହିଁ। 7:13
- ଶୟତାନ ତୁମ୍ଭମାନଙ୍କୁ ପ୍ରତାରଣା ନ କରୁ। 7:27
- (ମୁହମ୍ମଦ ﷺ) କୁହ: "ମୋର ପ୍ରଭୁ ନ୍ୟାୟର ଆଦେଶ ଦେଇଛନ୍ତି…" 7:29
- ସବୁ ବିଷୟରେ ଅଲ୍ଲାହ ନିର୍ଦ୍ଧାରିତ ସୀମା ପାଳନ କର। କଥା ଓ କାର୍ଯ୍ୟରେ ସୀମା ଲଙ୍ଘନ କର ନାହିଁ। ଖାଅ ଓ ପିଅ, କିନ୍ତୁ ଅପବ୍ୟୟ କର ନାହିଁ। ପ୍ରାର୍ଥନା ସମୟରେ ଭଲ ପୋଷାକ ପିନ୍ଧ। 7:31
- ଅଲ୍ଲାହ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀକୁ ଛଅ ଦିନରେ ସୃଷ୍ଟି କଲେ, ତା'ପରେ ଅର୍ଶ (ସିଂହାସନ) ଉପରେ (ତାଙ୍କ ମହିମା ଅନୁଯାୟୀ) ସ୍ଥିର ହେଲେ। 7:54
- ନିଜ ପ୍ରଭୁଙ୍କୁ ନମ୍ରତା ଓ ଗୋପନରେ ପ୍ରାର୍ଥନା କର। ସେ ସୀମା ଲଙ୍ଘନକାରୀମାନଙ୍କୁ ପସନ୍ଦ କରନ୍ତି ନାହିଁ। 7:55
- ପୃଥିବୀ ସୁଧୁରିବା ପରେ ତହିଁରେ ଅଶାନ୍ତି କର ନାହିଁ, ଏବଂ ତାଙ୍କୁ ଭୟ ଓ ଆଶା ସହିତ ପ୍ରାର୍ଥନା କର। 7:56
- କିନ୍ତୁ ଯେଉଁମାନେ ଖରାପ କର୍ମ କରିଥିଲେ ଏବଂ ତା'ପରେ ତୌବା କଲେ ଏବଂ ବିଶ୍ୱାସ କଲେ, ନିଶ୍ଚିତ ଭାବରେ ତୁମ୍ଭର ପ୍ରଭୁ ତା'ପରେ କ୍ଷମାଶୀଳ, ଦୟାବାନ। 7:153
- (ମୁହମ୍ମଦ ﷺ) କୁହ: "ହେ ମାନବମାନେ! ନିଶ୍ଚିତ ଭାବରେ ମୁଁ ତୁମ୍ଭ ସମସ୍ତଙ୍କ ନିକଟକୁ ଅଲ୍ଲାହଙ୍କ ରସୂଲ…" 7:158
- (ସବୁ) ସୁନ୍ଦର ନାମ ଅଲ୍ଲାହଙ୍କର, ତେଣୁ ସେଗୁଡ଼ିକ ଦ୍ୱାରା ତାଙ୍କୁ ଡାକ, ଏବଂ ଯେଉଁମାନେ ତାଙ୍କ ନାମରେ ବକ୍ରତା ଅବଲମ୍ବନ କରନ୍ତି, ସେମାନଙ୍କୁ ଛାଡ଼ିଦିଅ… 7:180
- ଅଲ୍ଲାହ ଯାକୁ ପଥଭ୍ରଷ୍ଟ କରନ୍ତି, ତା'ପାଇଁ କୌଣସି ପଥପ୍ରଦର୍ଶକ ନାହିଁ; ଏବଂ ସେ ସେମାନଙ୍କୁ ସେମାନଙ୍କ ବିଦ୍ରୋହରେ ଅନ୍ଧ ଭାବରେ ବୁଲିବାକୁ ଛାଡ଼ି ଦିଅନ୍ତି। 7:186
- କ୍ଷମା ଦେଖାଅ, ସତ୍କର୍ମର ଆଦେଶ ଦିଅ, ଏବଂ ମୂର୍ଖମାନଙ୍କଠାରୁ ଦୂରେଇ ରୁହ (ଅର୍ଥାତ୍ ସେମାନଙ୍କୁ ଦଣ୍ଡ ଦିଅ ନାହିଁ)। 7:199
- ଅନ୍ୟମାନଙ୍କ ଭୁଲ କ୍ଷମା କର। 7:199
- ଏବଂ ଯଦି ଶୟତାନର କୌଣସି ଦୁଷ୍ପ୍ରେରଣା ତୁମ୍ଭକୁ ସ୍ପର୍ଶ କରେ, ତେବେ ଅଲ୍ଲାହଙ୍କ ଶରଣ ଲୋଡ଼। ସେ ସବୁ ଶୁଣନ୍ତି, ସବୁ ଜାଣନ୍ତି। 7:200
- ବିଶ୍ୱାସୀମାନେ ତେଉଁମାନେ, ଯେଉଁମାନଙ୍କ ହୃଦୟ ଅଲ୍ଲାହଙ୍କ ସ୍ମରଣରେ ଭୟଭୀତ ହୁଏ, ଏବଂ ଯେତେବେଳେ ସେମାନଙ୍କୁ ତାଙ୍କ ଆୟତଗୁଡ଼ିକ ପଢ଼ି ଶୁଣାଯାଏ, ସେମାନଙ୍କ ବିଶ୍ୱାସ ବଢ଼ିଯାଏ… 8:2
- ଅଲ୍ଲାହ ଓ ତାଙ୍କ ରସୂଲଙ୍କ ସହିତ ବିଶ୍ୱାସଘାତ କର ନାହିଁ, ଏବଂ ଜାଣିଶୁଣି ନିଜ ଆମାନତ (ଓ ଅଲ୍ଲାହ ତୁମ୍ଭମାନଙ୍କୁ ଦେଇଥିବା ସବୁ କର୍ତ୍ତବ୍ୟ) ସହିତ ବିଶ୍ୱାସଘାତ କର ନାହିଁ। 8:27
- ଯଦି ତୁମ୍ଭମାନେ ଅଲ୍ଲାହଙ୍କ ଆଜ୍ଞା ପାଳନ କର ଏବଂ ତାଙ୍କୁ ଡର, ତେବେ ସେ ତୁମ୍ଭମାନଙ୍କୁ ଫୁରକାନ (ସତ୍ୟ-ମିଥ୍ୟା ପାର୍ଥକ୍ୟ କରିବାର ମାପଦଣ୍ଡ, କିମ୍ବା ପ୍ରତ୍ୟେକ କଷ୍ଟରୁ ବାହାରିବାର ଉପାୟ) ଦେବେ। 8:29
- ଅବିଶ୍ୱାସୀମାନେ ସେମାନଙ୍କ ସମ୍ପତ୍ତି (ଲୋକମାନଙ୍କୁ) ଅଲ୍ଲାହଙ୍କ ମାର୍ଗରୁ ରୋକିବା ପାଇଁ ଖର୍ଚ୍ଚ କରନ୍ତି, ଏବଂ ସେମାନେ ସେପରି ଖର୍ଚ୍ଚ କରିବେ; କିନ୍ତୁ ଶେଷରେ ତାହା ସେମାନଙ୍କ ପାଇଁ ଅନୁତାପ ହେବ। 8:36
- ଅବିଶ୍ୱାସୀମାନଙ୍କୁ କୁହ: ଯଦି ସେମାନେ (ଅବିଶ୍ୱାସରୁ) ନିବୃତ୍ତ ହୁଅନ୍ତି, ତେବେ ସେମାନଙ୍କର ଅତୀତ (ପାପ) କ୍ଷମା କରାଯିବ। କିନ୍ତୁ ଯଦି ସେମାନେ (ସେହି) ପ୍ରତି ଫେରନ୍ତି, ତେବେ ସେମାନଙ୍କ ପୂର୍ବବର୍ତ୍ତୀ (ଦଣ୍ଡିତ) ମାନଙ୍କ ଦୃଷ୍ଟାନ୍ତ ପୂର୍ବରୁ ହୋଇସାରିଛି (ସତର୍କବାଣୀ ଭାବରେ)। 8:38
- ଯେତେବେଳେ ତୁମ୍ଭମାନେ (ଶତ୍ରୁ) ସୈନ୍ୟର ସମ୍ମୁଖୀନ ହୁଅ, ଦୃଢ଼ ରୁହ ଏବଂ ଅଲ୍ଲାହଙ୍କ ନାମ (ଜିଭ ଓ ମନ ଉଭୟରେ) ବହୁତ ସ୍ମରଣ କର, ଯାହାଫଳରେ ତୁମ୍ଭମାନେ ସଫଳ ହୁଅ। 8:45
- ଯେଉଁମାନେ ଅହଙ୍କାରରେ ଓ ଲୋକମାନଙ୍କୁ ଦେଖାଇବା ପାଇଁ ନିଜ ଘରୁ ବାହାରିଥିଲେ, ଏବଂ (ଲୋକମାନଙ୍କୁ) ଅଲ୍ଲାହଙ୍କ ମାର୍ଗରୁ ରୋକିଥିଲେ, ସେମାନଙ୍କ ପରି ହୁଅ ନାହିଁ। 8:47
- ଅଲ୍ଲାହ କୌଣସି ଜାତିକୁ ଦେଇଥିବା ନେମତକୁ ସେମାନେ ନିଜ ଅବସ୍ଥା ପରିବର୍ତ୍ତନ ନ କରିବା ପର୍ଯ୍ୟନ୍ତ ପରିବର୍ତ୍ତନ କରନ୍ତି ନାହିଁ। 8:53
- ଅଲ୍ଲାହଙ୍କ ନିକଟରେ ସବୁଠାରୁ ଖରାପ ଜୀବ ହେଉଛନ୍ତି ଅବିଶ୍ୱାସୀମାନେ। 8:55
- ଅଲ୍ଲାହ ତାଙ୍କଠାରେ ବିଶ୍ୱାସ କରୁଥିବା ଲୋକମାନଙ୍କ ହୃଦୟ ମଧ୍ୟରେ ପ୍ରେମ ଓ ସ୍ନେହ ସୃଷ୍ଟି କରନ୍ତି। 8:63
- ଯେଉଁମାନେ ଆଶ୍ରୟ ମାଗନ୍ତି, ସେମାନଙ୍କୁ ସୁରକ୍ଷା ଦିଅ ଓ ସାହାଯ୍ୟ କର। 9:6
- ବହୁଦେବବାଦୀମାନଙ୍କ ପାଇଁ ଅଲ୍ଲାହଙ୍କ ମସଜିଦଗୁଡ଼ିକ ପରିଚାଳନା କରିବା ଉଚିତ ନୁହେଁ। 9:17
- ସେମାନେ (ଅବିଶ୍ୱାସୀମାନେ, ଯିହୂଦୀ ଓ ଖ୍ରୀଷ୍ଟିଆନମାନେ) ନିଜ ମୁଖରେ ଅଲ୍ଲାହଙ୍କ ଆଲୋକ (ଯାହା ସହିତ ମୁହମ୍ମଦ ﷺ ପଠାଯାଇଥିଲେ — ଇସଲାମୀ ଏକତ୍ୱବାଦ) ନିଭାଇବାକୁ ଚାହାନ୍ତି, କିନ୍ତୁ ଅଲ୍ଲାହ ତାଙ୍କ ଆଲୋକକୁ ସମ୍ପୂର୍ଣ୍ଣ ନ କରି ଅନ୍ୟ କିଛି ଅନୁମତି ଦିଅନ୍ତି ନାହିଁ, ଯଦିଓ ଅବିଶ୍ୱାସୀମାନେ ତାହା ଘୃଣା କରନ୍ତି। 9:32
- ସଦକା (ଯାକାତ) କେବଳ ଏମାନଙ୍କ ପାଇଁ: 1) ଗରିବ, 2) ଅଭାବଗ୍ରସ୍ତ, 3) ତାହା ସଂଗ୍ରହ କରୁଥିବା କର୍ମଚାରୀ, 4) ଯେଉଁମାନଙ୍କ ହୃଦୟ ଇସଲାମ ଆଡ଼କୁ ଆକର୍ଷିତ କରାଯିବ, 5) ଦାସ ମୁକ୍ତ କରିବା, 6) ଋଣଗ୍ରସ୍ତ, 7) ଅଲ୍ଲାହଙ୍କ ମାର୍ଗରେ (ମୁଜାହିଦମାନଙ୍କ ପାଇଁ), ଏବଂ 8) ପଥିକମାନଙ୍କ ପାଇଁ। 9:60
- ଯେ ଅଲ୍ଲାହ ଓ ତାଙ୍କ ରସୂଲ (ﷺ) ଙ୍କ ବିରୋଧ ଓ ଶତ୍ରୁତା କରେ, ତା'ପାଇଁ ଜାହନ୍ନମର ନର୍କ ଅଛି, ଯେଉଁଠାରେ ସେ ସଦାକାଳ ରହିବ। ତାହା ବହୁତ ବଡ଼ ଅପମାନ। 9:63
- ମୁନାଫିକ୍ ପୁରୁଷ ଓ ସ୍ତ୍ରୀମାନେ ପରସ୍ପର ସଦୃଶ। ସେମାନେ ଅଲ୍ଲାହଙ୍କୁ ଭୁଲିଗଲେ, ତେଣୁ ସେ ମଧ୍ୟ ସେମାନଙ୍କୁ ଭୁଲିଗଲେ। 9:67
- ପବିତ୍ରତା ପାଇଁ ଚେଷ୍ଟା କର। ମସଜିଦର ପବିତ୍ରତାକୁ ସମ୍ମାନ କର। 9:108
- ବହୁଦେବବାଦୀମାନଙ୍କ ପାଇଁ — ଯଦିଓ ସେମାନେ ସମ୍ପର୍କୀୟ — ସେମାନେ ନର୍କବାସୀ ବୋଲି ସ୍ପଷ୍ଟ ହେବା ପରେ (କାରଣ ସେମାନେ ଅବିଶ୍ୱାସୀ ଅବସ୍ଥାରେ ମରିଛନ୍ତି) (ପୟଗମ୍ବର ଓ ବିଶ୍ୱାସୀମାନଙ୍କ ପାଇଁ) କ୍ଷମା ମାଗିବା ଉଚିତ ନୁହେଁ। 9:113
- ଅଲ୍ଲାହଙ୍କ ଉପରେ ମିଥ୍ୟା ରଚନା କରୁଥିବା କିମ୍ବା ତାଙ୍କ ଆୟତଗୁଡ଼ିକୁ ଅସ୍ୱୀକାର କରୁଥିବା ବ୍ୟକ୍ତିଠାରୁ ଅଧିକ ଅତ୍ୟାଚାରୀ କିଏ? ନିଶ୍ଚିତ ଭାବରେ ଅପରାଧୀମାନେ ସଫଳ ହେବେ ନାହିଁ! 10:17
- ସେମାନେ ଅଲ୍ଲାହଙ୍କୁ ଛାଡ଼ି ଯାହା ସେମାନଙ୍କୁ କ୍ଷତି କିମ୍ବା ଲାଭ କରିପାରେ ନାହିଁ, ତାହାର ଉପାସନା କରନ୍ତି, ଏବଂ ସେମାନେ କୁହନ୍ତି: "ଏମାନେ ଅଲ୍ଲାହଙ୍କ ନିକଟରେ ଆମର ସୁପାରିଶକାରୀ।" କୁହ: "ତୁମ୍ଭେମାନେ କ'ଣ ଅଲ୍ଲାହଙ୍କୁ ଆକାଶ ଓ ପୃଥିବୀରେ ତାଙ୍କ ଅଜଣା ବିଷୟ ଜଣାଉଛ?" ସେ ପବିତ୍ର ଏବଂ ସେମାନେ ଯାହା ଅଂଶୀଦାର କରନ୍ତି, ତାଠାରୁ ଉଚ୍ଚ। 10:18
- ଖରାପ କର୍ମର ପ୍ରତିଫଳ ସେହିପରି ଖରାପ କର୍ମ। 10:27
- ସେ ହିଁ ଅଲ୍ଲାହ, ତୁମ୍ଭମାନଙ୍କର ସତ୍ୟ ପ୍ରଭୁ। ସତ୍ୟ ପରେ ପଥଭ୍ରଷ୍ଟତା ବ୍ୟତୀତ ଆଉ କ'ଣ ଅଛି? ତେବେ ତୁମ୍ଭମାନେ କେଉଁଆଡ଼କୁ ଫେରାଯାଉଛ? 10:32
- ସେମାନଙ୍କ ମଧ୍ୟରୁ ଅଧିକାଂଶ କେବଳ ଅନୁମାନର ଅନୁସରଣ କରନ୍ତି। ନିଶ୍ଚିତ ଭାବରେ ଅନୁମାନ ସତ୍ୟର କୌଣସି କାମରେ ଆସେ ନାହିଁ। 10:36
- ନିଶ୍ଚିତ ଭାବରେ! ଅଲ୍ଲାହ ଲୋକମାନଙ୍କ ପ୍ରତି କୌଣସି ଅତ୍ୟାଚାର କରନ୍ତି ନାହିଁ; କିନ୍ତୁ ଲୋକମାନେ ନିଜେ ନିଜ ପ୍ରତି ଅତ୍ୟାଚାର କରନ୍ତି। 10:44
- ଜାଣ ଯେ ଅଲ୍ଲାହଙ୍କ ଅନୁଗ୍ରହ ମନୁଷ୍ୟ ସଂଗ୍ରହ କିମ୍ବା ଜମା କରିପାରୁଥିବା ସବୁଠାରୁ ଉତ୍ତମ। 10:58
- ଅଲ୍ଲାହଙ୍କ ଆୟତଗୁଡ଼ିକୁ ଅସ୍ୱୀକାର କରୁଥିବା ଲୋକମାନଙ୍କ ମଧ୍ୟରେ ରୁହ ନାହିଁ, ନଚେତ୍ ତୁମ୍ଭମାନେ କ୍ଷତିଗ୍ରସ୍ତମାନଙ୍କ ମଧ୍ୟରେ ରହିବ। 10:95
- ଯଦି ଅଲ୍ଲାହ ତୁମ୍ଭକୁ କୌଣସି କ୍ଷତି ସ୍ପର୍ଶ କରାନ୍ତି, ତେବେ ତାଙ୍କ ବ୍ୟତୀତ ଆଉ କେହି ତାହା ଦୂର କରିପାରିବେ ନାହିଁ; ଏବଂ ଯଦି ସେ ତୁମ୍ଭ ପାଇଁ ଭଲ ଚାହାନ୍ତି, ତେବେ ତାଙ୍କ ଅନୁଗ୍ରହକୁ କେହି ଫେରାଇ ପାରିବେ ନାହିଁ, ସେ ତାହା ନିଜ ଦାସମାନଙ୍କ ମଧ୍ୟରୁ ଯାକୁ ଇଚ୍ଛା ଦିଅନ୍ତି। 10:107
- ପୃଥିବୀରେ କୌଣସି ଚଳପ୍ରଚଳ ଜୀବ ନାହିଁ, ଯାହାର ଜୀବିକା ଅଲ୍ଲାହଙ୍କ ଉପରେ ନାହିଁ। ଏବଂ ସେ ତା'ର ବାସସ୍ଥାନ ଓ ଗଚ୍ଛିତ ସ୍ଥାନ (ଗର୍ଭାଶୟ, କବର ଇତ୍ୟାଦି) ଜାଣନ୍ତି। 11:6
- ଯଦି ଆମେ ମନୁଷ୍ୟକୁ ନିଜ ତରଫରୁ ଦୟାର ସ୍ୱାଦ ଚଖାଇବା, ତା'ପରେ ତାହା ତା'ଠାରୁ ଛଡ଼ାଇ ନେବା, ତେବେ ସେ ନିରାଶ ଓ କୃତଘ୍ନ ହୁଏ। 11:9
- ଯେ ସାଂସାରିକ ଜୀବନ ଓ ତା'ର ବୈଭବ ଚାହେଁ, ଆମେ ସେମାନଙ୍କୁ ତହିଁରେ ସେମାନଙ୍କ କର୍ମର ସମ୍ପୂର୍ଣ୍ଣ ପୁରସ୍କାର ଦେବୁ ଏବଂ ସେମାନଙ୍କୁ ତହିଁରେ କୌଣସି କମ୍ କରାଯିବ ନାହିଁ। 11:15
- ଆମେ ସେମାନଙ୍କ ପ୍ରତି ଅତ୍ୟାଚାର କରିନାହୁଁ, କିନ୍ତୁ ସେମାନେ ନିଜେ ନିଜ ପ୍ରତି ଅତ୍ୟାଚାର କଲେ। ସେମାନେ ଅଲ୍ଲାହଙ୍କୁ ଛାଡ଼ି ଯାହାଙ୍କୁ ଡାକୁଥିଲେ, ସେମାନଙ୍କ ଦେବତାମାନେ ଯେତେବେଳେ ତୁମ୍ଭର ପ୍ରଭୁଙ୍କ ଆଦେଶ ଆସିଲା, ସେମାନଙ୍କ କୌଣସି କାମରେ ଆସିଲେ ନାହିଁ, ଏବଂ ସେମାନଙ୍କ ବିନାଶ ବ୍ୟତୀତ ଆଉ କିଛି ବଢ଼ାଇ ନ ଥିଲେ। 11:101
- ଯେଉଁ ଦିନ ତାହା (ଦଣ୍ଡ) ଆସିବ, ତାଙ୍କ (ଅଲ୍ଲାହ) ଙ୍କ ଅନୁମତି ବିନା କେହି କଥା କହିବେ ନାହିଁ। ସେମାନଙ୍କ ମଧ୍ୟରୁ କେହି ଦୁର୍ଭାଗ୍ୟଶାଳୀ ଓ (କେହି) ସୌଭାଗ୍ୟଶାଳୀ ହେବେ। 11:105
- ଦୁର୍ଭାଗ୍ୟଶାଳୀମାନେ ନର୍କରେ ରହିବେ, ସେଠାରେ ସେମାନଙ୍କର ବିଳାପ ଓ କ୍ରନ୍ଦନ ହେବ। 11:106
- ସେମାନେ ସେଠାରେ ସଦାକାଳ ରହିବେ, ଯେପର୍ଯ୍ୟନ୍ତ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀ ରହିବ, କିନ୍ତୁ ତୁମ୍ଭର ପ୍ରଭୁ ଯାହା ଇଚ୍ଛା କରନ୍ତି। ନିଶ୍ଚିତ ଭାବରେ ତୁମ୍ଭର ପ୍ରଭୁ ଯାହା ଇଚ୍ଛା କରନ୍ତି, ତାହା କରନ୍ତି। 11:107
- ଏବଂ ସୌଭାଗ୍ୟଶାଳୀମାନେ ସ୍ୱର୍ଗରେ ରହିବେ, ସେଠାରେ ସଦାକାଳ ରହିବେ, ଯେପର୍ଯ୍ୟନ୍ତ ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀ ରହିବ, କିନ୍ତୁ ତୁମ୍ଭର ପ୍ରଭୁ ଯାହା ଇଚ୍ଛା କରନ୍ତି, ଅବ୍ୟାହତ ଦାନ ଭାବରେ। 11:108
- ଅତ୍ୟାଚାରୀମାନଙ୍କ ପ୍ରତି ଆଭିମୁଖ୍ୟ ଦେଖାଅ ନାହିଁ, ନଚେତ୍ ନର୍କ ତୁମ୍ଭମାନଙ୍କୁ ସ୍ପର୍ଶ କରିବ, ଏବଂ ଅଲ୍ଲାହ ବ୍ୟତୀତ ତୁମ୍ଭମାନଙ୍କର କୌଣସି ରକ୍ଷକ ନ ଥିବ, ଏବଂ ତୁମ୍ଭମାନଙ୍କୁ ସାହାଯ୍ୟ ମଧ୍ୟ କରାଯିବ ନାହିଁ। 11:113
- ଦିନର ଦୁଇ ପ୍ରାନ୍ତରେ ଓ ରାତ୍ରିର କେତେକ ଘଣ୍ଟାରେ ପ୍ରାର୍ଥନା ପ୍ରତିଷ୍ଠା କର (ଅର୍ଥାତ୍ 5 ଓକ୍ତ ପ୍ରାର୍ଥନା)। ସତ୍କର୍ମଗୁଡ଼ିକ ଦୁଷ୍କର୍ମଗୁଡ଼ିକୁ (ଅର୍ଥାତ୍ ସାନ ପାପ) ଦୂର କରେ। 11:114
- ଆକାଶମଣ୍ଡଳ ଓ ପୃଥିବୀର ଅଦୃଶ୍ୟ ଜ୍ଞାନ ଅଲ୍ଲାହଙ୍କର, ଏବଂ ସମସ୍ତ କାର୍ଯ୍ୟ ତାଙ୍କ ନିକଟକୁ (ନିଷ୍ପତ୍ତି ପାଇଁ) ଫେରାଯାଏ। 11:123
- ଆଦେଶ (ବା ନିର୍ଣ୍ଣୟ) କେବଳ ଅଲ୍ଲାହଙ୍କର। ସେ ଆଦେଶ ଦେଇଛନ୍ତି ଯେ ତୁମ୍ଭମାନେ ତାଙ୍କ ବ୍ୟତୀତ ଆଉ କାହାରି ଉପାସନା କର ନାହିଁ (ଏକତ୍ୱବାଦ), ତାହା ସିଧା ଧର୍ମ, କିନ୍ତୁ ଅଧିକାଂଶ ଲୋକ ଜାଣନ୍ତି ନାହିଁ। 12:40
- ଅଲ୍ଲାହଙ୍କ ଦୟାରୁ କେବେ ନିରାଶ ହୁଅ ନାହିଁ। 12:87
- ଏବଂ ଅଧିକାଂଶ ଲୋକ ବିଶ୍ୱାସ କରିବେ ନାହିଁ, ଯଦିଓ ତୁମ୍ଭେ ଅତ୍ୟନ୍ତ ଇଚ୍ଛା କର। 12:103
- ଏବଂ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଅଧିକାଂଶ ଅଲ୍ଲାହଙ୍କୁ ବିଶ୍ୱାସ କରନ୍ତି ନାହିଁ, କିନ୍ତୁ ସେମାନେ ଅଂଶୀଦାର କରନ୍ତି (ଅର୍ଥାତ୍ ସେମାନେ ବହୁଦେବବାଦୀ)। 12:106
- ଏହା (କୁରଆନ) କୌଣସି ରଚିତ କଥା ନୁହେଁ, ବରଂ ଏହା ପୂର୍ବବର୍ତ୍ତୀ ଗ୍ରନ୍ଥଗୁଡ଼ିକ (ତୌରାତ, ଇଞ୍ଜୀଲ ଓ ଅନ୍ୟ ଗ୍ରନ୍ଥଗୁଡ଼ିକ) ର ସତ୍ୟତା ପ୍ରମାଣ ଏବଂ ପ୍ରତ୍ୟେକ ବିଷୟର ବିସ୍ତୃତ ବ୍ୟାଖ୍ୟା, ଏବଂ ବିଶ୍ୱାସୀ ଲୋକମାନଙ୍କ ପାଇଁ ପଥପ୍ରଦର୍ଶନ ଓ ଦୟା। 12:111
- ଅଲ୍ଲାହ ଯାକୁ ଇଚ୍ଛା ଜୀବିକା ପ୍ରଶସ୍ତ କରନ୍ତି ଏବଂ (ଯାକୁ ଇଚ୍ଛା) ସୀମିତ କରନ୍ତି। 13:26
- ଅଲ୍ଲାହଙ୍କୁ ଜିକ୍ର (ସ୍ମରଣ) ଦ୍ୱାରା ବହୁତ ସ୍ମରଣ କର। ଅଲ୍ଲାହଙ୍କୁ ବିଶ୍ୱାସ କରୁଥିବା ଲୋକମାନେ ତାଙ୍କ ସ୍ମରଣରେ ହୃଦୟର ଶାନ୍ତି ପାଆନ୍ତି। 13:28
- ଯେଉଁମାନେ ବିଶ୍ୱାସ କରନ୍ତି ଏବଂ ସତ୍କର୍ମ କରନ୍ତି, ସେମାନଙ୍କୁ ଆନନ୍ଦ ଓ ମାନସିକ ଶାନ୍ତି ଦିଆଯାଏ। 13:29
- ଯେଉଁମାନେ ପରଲୋକ ଅପେକ୍ଷା ସାଂସାରିକ ଜୀବନକୁ ପ୍ରାଧାନ୍ୟ ଦିଅନ୍ତି, ଏବଂ (ଲୋକମାନଙ୍କୁ) ଅଲ୍ଲାହଙ୍କ ମାର୍ଗ (ଇସଲାମ) ରୁ ରୋକନ୍ତି, ଏବଂ ତହିଁରେ ବକ୍ରତା ଖୋଜନ୍ତି — ସେମାନେ ଦୂର ପଥଭ୍ରଷ୍ଟତାରେ ଅଛନ୍ତି। 14:3
- ଉପାସନାରେ ନମ୍ରତା ଓ କୃତଜ୍ଞତା ଅବଲମ୍ବନ କର। 14:7
- ଯେଉଁମାନେ ସେମାନଙ୍କ ପ୍ରଭୁଙ୍କୁ ଅସ୍ୱୀକାର କରନ୍ତି, ସେମାନଙ୍କ କର୍ମର ଉଦାହରଣ ଛାର ପରି, ଯାହା ଉପରେ ଝଡ଼ ଦିନରେ ପବନ ଜୋରରେ ବହେ; ସେମାନେ ନିଜ କର୍ମରୁ କିଛି ପାଇବେ ନାହିଁ। 14:18
- ଅଲ୍ଲାହ ବିଶ୍ୱାସୀମାନଙ୍କୁ ଏହି ଦୁନିଆରେ (ଅର୍ଥାତ୍ ସେମାନେ କେବଳ ଅଲ୍ଲାହଙ୍କ ଉପାସନା ଜାରି ରଖିବେ) ଏବଂ ପରଲୋକରେ ଦୃଢ଼ ବାକ୍ୟରେ ସ୍ଥିର କରନ୍ତି। 14:27
- ଅଲ୍ଲାହ ଅତ୍ୟାଚାରୀ (ବହୁଦେବବାଦୀ, ଜୁଲମୀ ଇତ୍ୟାଦି) ମାନେ ଯାହା କରୁଛନ୍ତି, ତାହା ପ୍ରତି ଅଜାଣତ ବୋଲି ଭାବ ନାହିଁ; କିନ୍ତୁ ସେ ସେମାନଙ୍କୁ ସେହି ଦିନ ପର୍ଯ୍ୟନ୍ତ ଅବକାଶ ଦିଅନ୍ତି, ଯେତେବେଳେ ଆଖି ଭୟରେ ଖୋଲା ହୋଇଥିବ। 14:42
- ଯାହାଫଳରେ ଅଲ୍ଲାହ ପ୍ରତ୍ୟେକ ବ୍ୟକ୍ତିକୁ ତା'ର କର୍ମ ଅନୁସାରେ ପ୍ରତିଫଳ ଦେବେ। ନିଶ୍ଚିତ ଭାବରେ ଅଲ୍ଲାହ ହିସାବ ନେବାରେ ଶୀଘ୍ର। 14:51
- ଏବଂ ନିଶ୍ଚିତ ଭାବରେ ଆମେ ମନୁଷ୍ୟକୁ ଖଣଖଣ ଶବ୍ଦ କରୁଥିବା ମାଟିରୁ, କଳା ପରିବର୍ତ୍ତିତ କାଦୁଅରୁ ସୃଷ୍ଟି କଲୁ। 15:26
- ଏବଂ ଜିନ୍ନମାନଙ୍କୁ ଆମେ ଏହା ପୂର୍ବରୁ ଧୂଆଁବିହୀନ ଅଗ୍ନି ଜ୍ୱାଳାରୁ ସୃଷ୍ଟି କଲୁ। 15:27
- ତା'ର (ନର୍କର) ସାତଟି ଦ୍ୱାର ଅଛି; ପ୍ରତ୍ୟେକ ଦ୍ୱାର ପାଇଁ (ବିଶେଷ) ପାପୀମାନଙ୍କର ଏକ ଶ୍ରେଣୀ ଅଛି। 15:44
- ସେ ମନୁଷ୍ୟକୁ ବୀର୍ଯ୍ୟର ଏକ ବିନ୍ଦୁ (ପୁରୁଷ ଓ ସ୍ତ୍ରୀର ଯୌନ ନିଃସ୍ରାବର ମିଶ୍ରଣ) ରୁ ସୃଷ୍ଟି କଲେ, ତା'ପରେ ସେ (ମନୁଷ୍ୟ) ଖୋଲା ବିପକ୍ଷ ହୋଇଯାଏ। 16:4
- ଏବଂ ଚତୁଷ୍ପଦ ଜନ୍ତୁମାନଙ୍କୁ, ସେ ସେମାନଙ୍କୁ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ସୃଷ୍ଟି କଲେ; ସେମାନଙ୍କରେ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ଉଷ୍ମତା (ଉଷ୍ମ ବସ୍ତ୍ର) ଏବଂ ବହୁତ ଉପକାରିତା ଅଛି, ଏବଂ ସେମାନଙ୍କରୁ ତୁମ୍ଭମାନେ ଖାଅ। 16:5
- ଏବଂ (ସେ ସୃଷ୍ଟି କଲେ) ଘୋଡ଼ା, ଖଚର ଓ ଗଧ, ତୁମ୍ଭମାନେ ଚଢ଼ିବା ପାଇଁ ଏବଂ ସଜ୍ଜା ଭାବରେ। ଏବଂ ସେ ଏପରି (ଅନ୍ୟ) ଜିନିଷ ସୃଷ୍ଟି କରନ୍ତି, ଯାହା ତୁମ୍ଭମାନେ ଜାଣ ନାହିଁ। 16:8
- ସେ ହିଁ ଆକାଶରୁ ଜଳ (ବର୍ଷା) ବର୍ଷାନ୍ତି; ତାହାରୁ ତୁମ୍ଭମାନେ ପିଅ ଏବଂ ତାହାରୁ ଗଛ ବଢ଼େ, ଯେଉଁଥିରେ ତୁମ୍ଭମାନେ ନିଜ ଚତୁଷ୍ପଦମାନଙ୍କୁ ଚରାଅ। 16:10
- ସେ ହିଁ ସମୁଦ୍ରକୁ ତୁମ୍ଭମାନଙ୍କ ବଶୀଭୂତ କରିଛନ୍ତି, ଯାହାଫଳରେ ତୁମ୍ଭମାନେ ତାହାରୁ ତାଜା ମାଂସ (ମାଛ) ଖାଇପାର ଏବଂ ତାହାରୁ ଅଳଙ୍କାର ବାହାର କରି ପିନ୍ଧିପାର। 16:14
- ସେ ପୃଥିବୀରେ ସ୍ଥିର ପର୍ବତ ରଖିଛନ୍ତି, ଯାହାଫଳରେ ତାହା ତୁମ୍ଭମାନଙ୍କ ସହିତ ନ ଥରେ, ଏବଂ ନଦୀ ଓ ପଥ (ସୃଷ୍ଟି କରିଛନ୍ତି), ଯାହାଫଳରେ ତୁମ୍ଭମାନେ ପଥ ପାଇପାର। 16:15
- ଯେ ସୃଷ୍ଟି କରେ, ସେ କ'ଣ ଯେ ସୃଷ୍ଟି କରେ ନାହିଁ, ତା' ସହିତ ସମାନ? ତୁମ୍ଭମାନେ କ'ଣ ଚିନ୍ତା କର ନାହିଁ? 16:17
- ଯଦି ତୁମ୍ଭମାନେ ଅଲ୍ଲାହଙ୍କ ଅନୁଗ୍ରହ ଗଣନା କରିବାକୁ ଚାହାଁ, ତେବେ କେବେ ବି ଗଣନା କରିପାରିବ ନାହିଁ। 16:18
- ଅଲ୍ଲାହ ତୁମ୍ଭମାନେ ଯାହା ଲୁଚାଅ ଏବଂ ଯାହା ପ୍ରକାଶ କର, ତାହା ଜାଣନ୍ତି। 16:19
- ସେମାନେ (ବହୁଦେବବାଦୀମାନେ) ଅଲ୍ଲାହଙ୍କୁ ଛାଡ଼ି ଯାହା ପ୍ରାର୍ଥନା କରନ୍ତି, ସେମାନେ କିଛି ସୃଷ୍ଟି କରନ୍ତି ନାହିଁ, ବରଂ ସେମାନେ ନିଜେ ସୃଷ୍ଟ। 16:20
- (ସେମାନେ) ମୃତ, ନିର୍ଜୀବ, ଏବଂ ସେମାନେ ଜାଣନ୍ତି ନାହିଁ ଯେ କେବେ ସେମାନଙ୍କୁ ପୁନରୁତ୍ଥିତ କରାଯିବ। 16:21
- ଯେତେବେଳେ ଆମେ କୌଣସି ଜିନିଷ ଇଚ୍ଛା କରୁ, ତା' ପାଇଁ ଆମର କଥା ହେଉଛି କେବଳ "ହୁଅ!" କୁହ, ଏବଂ ତାହା ହୋଇଯାଏ। 16:40
- ଯେଉଁମାନେ ଖରାପ ଷଡ଼ଯନ୍ତ୍ର କରନ୍ତି, ସେମାନେ କ'ଣ ଏଥିରେ ନିରାପଦ ଅନୁଭବ କରନ୍ତି ଯେ ଅଲ୍ଲାହ ସେମାନଙ୍କୁ ପୃଥିବୀରେ ବୁଡ଼ାଇ ଦେବେ ନାହିଁ, କିମ୍ବା ସେମାନଙ୍କ ଉପରେ ଦଣ୍ଡ ଆସିବ ନାହିଁ, ଯାହା ସେମାନେ ଆଶା କରନ୍ତି ନାହିଁ? 16:45
- ତୁମ୍ଭମାନଙ୍କ ନିକଟରେ ଥିବା ସବୁ ନେମତ ଓ ଭଲ ଜିନିଷ ଅଲ୍ଲାହଙ୍କ ତରଫରୁ। ତା'ପରେ ଯେତେବେଳେ ତୁମ୍ଭମାନଙ୍କୁ କଷ୍ଟ ସ୍ପର୍ଶ କରେ, ତେବେ ତୁମ୍ଭମାନେ ତାଙ୍କୁ ହିଁ ଚିତ୍କାର କରି ଡାକ। 16:53
- ତା'ପରେ ଯେତେବେଳେ ସେ ତୁମ୍ଭମାନଙ୍କୁ କଷ୍ଟରୁ ମୁକ୍ତ କରନ୍ତି, ତୁରନ୍ତ ତୁମ୍ଭମାନଙ୍କ ମଧ୍ୟରୁ କେହି କେହି ସେମାନଙ୍କ ପ୍ରଭୁ (ଅଲ୍ଲାହ) ଙ୍କ ସହିତ ଅଂଶୀଦାର କରନ୍ତି। 16:54
- ଚତୁଷ୍ପଦମାନଙ୍କରେ ତୁମ୍ଭମାନଙ୍କ ପାଇଁ ଶିକ୍ଷା ଅଛି। ଆମେ ତୁମ୍ଭମାନଙ୍କୁ ସେମାନଙ୍କ ପେଟ ଭିତରୁ, ଗୋବର ଓ ରକ୍ତ ମଧ୍ୟରୁ, ଶୁଦ୍ଧ ଦୁଗ୍ଧ ପାନ କରାଉ, ଯାହା ପିଉଥିବା ଲୋକମାନଙ୍କ ପାଇଁ ସ୍ୱାଦିଷ୍ଟ। 16:66
- ତେଣୁ ଅଲ୍ଲାହଙ୍କ ପାଇଁ ଉପମା ଦିଅ ନାହିଁ (କାରଣ ତାଙ୍କ ସହିତ ସମାନ କିଛି ନାହିଁ, ଏବଂ ସେ କାହା ସହିତ ମଧ୍ୟ ସମାନ ନୁହଁନ୍ତି)। ଅଲ୍ଲାହ ଜାଣନ୍ତି, କିନ୍ତୁ ତୁମ୍ଭମାନେ ଜାଣ ନାହିଁ। 16:74
- ଜାଣ ଯେ ଅଲ୍ଲାହ ମନୁଷ୍ୟକୁ ଶ୍ରବଣ, ଦୃଷ୍ଟି, ବୁଦ୍ଧି ଓ ଭାବନା ଦେଇଛନ୍ତି, ଯାହାଫଳରେ ସେମାନେ କୃତଜ୍ଞ ହୁଅନ୍ତି। 16:78
- ଲୋଭ ଓ କୃପଣତାରୁ ଦୂରେଇ ରୁହ। 16:97
- ଯେତେବେଳେ ତୁମ୍ଭେ କୁରଆନ ପଢ଼ିବାକୁ ଚାହଁ, ଶୟତାନଠାରୁ ଅଲ୍ଲାହଙ୍କ ଶରଣ ଲୋଡ଼। 16:98
- ଜାଣ ଯେ ଅଜ୍ଞତାବଶତଃ କରାଯାଇଥିବା ଭୁଲ, ଯଦି ବ୍ୟକ୍ତି ତୌବା କରେ ଏବଂ ନିଜକୁ ସୁଧାରେ, ତେବେ ତାହା କ୍ଷମା କରାଯାଏ। 16:119
- (ମୁହମ୍ମଦ ﷺ) ନିଜ ପ୍ରଭୁଙ୍କ ମାର୍ଗ (ଇସଲାମ) ପ୍ରତି ଜ୍ଞାନ ଓ ସଦୁପଦେଶ ଦ୍ୱାରା ଡାକ, ଏବଂ ସେମାନଙ୍କ ସହିତ ଉତ୍ତମ ଢଙ୍ଗରେ ତର୍କ କର। ଅନ୍ୟମାନଙ୍କୁ ଅଲ୍ଲାହଙ୍କ ମାର୍ଗକୁ ଡାକିବା ଜ୍ଞାନ ଓ ସୌଜନ୍ୟତା ସହିତ କରାଯିବା ଉଚିତ। 16:125
- ଅଲ୍ଲାହ ସେମାନଙ୍କ ସହିତ ଅଛନ୍ତି ଯେଉଁମାନେ ତାଙ୍କୁ ଡରନ୍ତି (ଯେଉଁମାନେ ତାଙ୍କ ପ୍ରତି ନିଜ କର୍ତ୍ତବ୍ୟ ପାଳନ କରନ୍ତି) ଏବଂ ଯେଉଁମାନେ ସତ୍କର୍ମ କରନ୍ତି। 16:128
- ଏହି କୁରଆନ ସବୁଠାରୁ ସିଧା ଓ ନ୍ୟାୟସଙ୍ଗତ ମାର୍ଗ ଦେଖାଏ। 17:9
- କେହି ଅନ୍ୟର ପାପ ବୋଝ ବହନ କରିବ ନାହିଁ। 17:15
- ଯେ ପରଲୋକ ଚାହେଁ ଏବଂ ତା' ପାଇଁ ଉପଯୁକ୍ତ ପ୍ରୟାସ କରେ, ଏବଂ ସେ ବିଶ୍ୱାସୀ, ତେବେ ସେମାନଙ୍କର ପ୍ରୟାସ (ଅଲ୍ଲାହଙ୍କ ଦ୍ୱାରା) ପ୍ରଶଂସିତ ଓ ପୁରସ୍କୃତ ହେବ। 17:19
- ପିତାମାତାଙ୍କୁ ସମ୍ମାନ କର ଏବଂ ସେମାନଙ୍କ ସହିତ ଦୟାଳୁ ବ୍ୟବହାର କର। ପିତାମାତାଙ୍କ ପ୍ରତି ବିଧେୟ ହୁଅ। ସେମାନଙ୍କୁ ଅପମାନଜନକ କଥା କୁହ ନାହିଁ। ତୁମ୍ଭର ପ୍ରଭୁ ଆଦେଶ ଦେଇଛନ୍ତି ଯେ ତୁମ୍ଭମାନେ ତାଙ୍କ ବ୍ୟତୀତ ଆଉ କାହାରି ଉପାସନା କର ନାହିଁ। ଏବଂ ପିତାମାତାଙ୍କ ସହିତ ସଦ୍ୟବହାର କର। ଯଦି ସେମାନଙ୍କ ମଧ୍ୟରୁ ଜଣେ କିମ୍ବା ଉଭୟ ତୁମ୍ଭ ଜୀବନରେ ବୃଦ୍ଧାବସ୍ଥାକୁ ପହଞ୍ଚନ୍ତି, ତେବେ ସେମାନଙ୍କୁ "ଛି:" କୁହ ନାହିଁ, ଏବଂ ସେମାନଙ୍କୁ ତିରସ୍କାର କର ନାହିଁ, ବରଂ ସେମାନଙ୍କୁ ସମ୍ମାନଜନକ କଥା କୁହ। 17:23
- ଏବଂ ସେମାନଙ୍କ ପାଇଁ ନମ୍ରତା ଓ ଦୟାର ପକ୍ଷ ତଳକୁ ନମାଅ, ଏବଂ କୁହ: "ହେ ମୋର ପ୍ରଭୁ! ସେମାନଙ୍କ ପ୍ରତି ଦୟା କର, ଯେପରି ସେମାନେ ମୋତେ ଶୈଶବରେ ପାଳନ ପୋଷଣ କରିଥିଲେ।" 17:24
- ନିଶ୍ଚିତ ଭାବରେ ଅପବ୍ୟୟକାରୀମାନେ ଶୟତାନର ଭାଇ, ଏବଂ ଶୟତାନ ନିଜ ପ୍ରଭୁଙ୍କ ପ୍ରତି କୃତଘ୍ନ। 17:27
- ଟଙ୍କା ଅପବ୍ୟୟ କର ନାହିଁ। 17:29
- ଦାରିଦ୍ର୍ୟ ଭୟରେ ନିଜ ସନ୍ତାନମାନଙ୍କୁ ହତ୍ୟା କର ନାହିଁ। 17:31
- ବ୍ୟଭିଚାରର ନିକଟକୁ ଯାଅ ନାହିଁ। ବିବାହର ପବିତ୍ରତା ରକ୍ଷା କର ଏବଂ ବ୍ୟଭିଚାରରୁ ଦୂରେଇ ରୁହ। 17:32
- ଯେତେବେଳେ ମାପ, ପୂର୍ଣ୍ଣ ପରିମାଣ ଦିଅ ଏବଂ ସିଧା ତରାଜୁରେ ଓଜନ କର। ତାହା ଭଲ (ଲାଭଦାୟକ) ଏବଂ ଶେଷରେ ଉତ୍ତମ। 17:35
- (ମନୁଷ୍ୟ) ଯାହାର ତୁମ୍ଭକୁ ଜ୍ଞାନ ନାହିଁ, ତା'ର ଅନୁସରଣ କର ନାହିଁ (ଉଦାହରଣ: "ମୁଁ ଦେଖିଛି" କହିବା, କିନ୍ତୁ ସେ ଦେଖି ନାହିଁ, କିମ୍ବା "ମୁଁ ଶୁଣିଛି" କହିବା, କିନ୍ତୁ ସେ ଶୁଣି ନାହିଁ)। 17:36
- ନମ୍ର ହୁଅ ଏବଂ ଅହଙ୍କାରୀ ହୁଅ ନାହିଁ। ପୃଥିବୀରେ ଅହଙ୍କାରରେ ଚାଲ ନାହିଁ। ନିଶ୍ଚିତ ଭାବରେ ତୁମ୍ଭେ ପୃଥିବୀକୁ ବିଦୀର୍ଣ୍ଣ କରିପାରିବ ନାହିଁ, ଏବଂ ପର୍ବତର ଉଚ୍ଚତା ମଧ୍ୟ ପାଇପାରିବ ନାହିଁ। 17:37
- ତୁମ୍ଭର ପ୍ରଭୁ ତୁମ୍ଭମାନଙ୍କୁ ଭଲ ଭାବରେ ଜାଣନ୍ତି; ଯଦି ସେ ଇଚ୍ଛା କରନ୍ତି, ତୁମ୍ଭମାନଙ୍କ ପ୍ରତି ଦୟା କରିବେ, କିମ୍ବା ଯଦି ଇଚ୍ଛା କରନ୍ତି, ତୁମ୍ଭମାନଙ୍କୁ ଦଣ୍ଡ ଦେବେ। 17:54
- ଯେ ଏହି ଦୁନିଆରେ ଅନ୍ଧ (ଅର୍ଥାତ୍ ଅଲ୍ଲାହଙ୍କ ନିଶାନୀ ଦେଖେ ନାହିଁ ଏବଂ ତାଙ୍କୁ ବିଶ୍ୱାସ କରେ ନାହିଁ), ସେ ପରଲୋକରେ ମଧ୍ୟ ଅନ୍ଧ ହେବ, ଏବଂ ପଥରୁ ଅଧିକ ବିଚ୍ୟୁତ ହେବ। 17:72
- ନିର୍ଦ୍ଧାରିତ ପ୍ରାର୍ଥନା ସମୟଗୁଡ଼ିକୁ ପାଳନ କର। 17:78
- ନିଶ୍ଚିତ ଭାବରେ ଆମେ ଏହି କୁରଆନରେ ଲୋକମାନଙ୍କ ପାଇଁ ପ୍ରତ୍ୟେକ ପ୍ରକାର ଉଦାହରଣ ବିସ୍ତୃତ ଭାବରେ ବର୍ଣ୍ଣନା କରିଛୁ, କିନ୍ତୁ ଅଧିକାଂଶ ଲୋକ (ସତ୍ୟକୁ) ଅସ୍ୱୀକାର କରନ୍ତି ଏବଂ କେବଳ ଅବିଶ୍ୱାସକୁ ଗ୍ରହଣ କରନ୍ତି। 17:89
- ଆମେ ଏହି କୁରଆନରେ ଲୋକମାନଙ୍କ ପାଇଁ ପ୍ରତ୍ୟେକ ପ୍ରକାର ଉଦାହରଣ ଉପସ୍ଥାପନ କରିଛୁ। କିନ୍ତୁ ମନୁଷ୍ୟ ସବୁଠାରୁ ଅଧିକ ବିତର୍କପ୍ରିୟ। 18:54
- ସେମାନଙ୍କର ପ୍ରତିଫଳ ଜାହନ୍ନମ; କାରଣ ସେମାନେ ଅବିଶ୍ୱାସ କଲେ ଏବଂ ମୋର ଆୟତ ଓ ରସୂଲମାନଙ୍କୁ ଉପହାସ ଓ ଠଟ୍ଟାର ବିଷୟ କଲେ। 18:106
- ଅଲ୍ଲାହ (ଙ୍କ ମହିମା) ପାଇଁ ସନ୍ତାନ ରହିବା ଉଚିତ ନୁହେଁ (ଏହା ଖ୍ରୀଷ୍ଟିଆନମାନେ ଅଲ୍ଲାହଙ୍କ ବିରୁଦ୍ଧରେ କରିଥିବା ନିନ୍ଦାକୁ ସୂଚିତ କରେ, ଯେ ଈସା (ଯୀଶୁ) ଅଲ୍ଲାହଙ୍କ ପୁତ୍ର)। ସେ ପବିତ୍ର (ଏବଂ ସେମାନେ ଯାହା ଅଂଶୀଦାର କରନ୍ତି, ତାଠାରୁ ଉଚ୍ଚ)। 19:35
- ଲୋକମାନଙ୍କ ସହିତ ନମ୍ରତାର ସହିତ କହ। 20:44
- ସତ୍କର୍ମରେ ପ୍ରତିଦ୍ୱନ୍ଦ୍ୱିତା କର। 21:90
- ଅସାର କଥାରୁ ଦୂରେଇ ରୁହ। 23:3
- ନିଜର ଲଜ୍ଜା ରକ୍ଷା କର। 23:5
- ନିଜ ହୃଦୟକୁ ପାପପ୍ରବଣତାରୁ ରକ୍ଷା କର। 23:97
- ଅନ୍ୟମାନଙ୍କୁ କ୍ଷମା କର ଏବଂ ସେମାନଙ୍କ ଭୁଲ ମାଫ କର। 24:22
- ଅନ୍ୟମାନଙ୍କ ଗୋପନୀୟତାକୁ ସମ୍ମାନ କର, ବିଶେଷ କରି ସେମାନଙ୍କ ଘରେ। ପଡ଼ୋଶୀମାନଙ୍କ ଅଧିକାର ପୂରଣ କର। 24:27
- (ପୁରୁଷ ଓ ସ୍ତ୍ରୀ ଉଭୟେ) ନିଜ ଦୃଷ୍ଟି ନତ କର। ନିଜର ଲଜ୍ଜା ଓ ସତୀତ୍ୱ ରକ୍ଷା କର। 24:30
- ପୋଷାକ ଓ ଆଚରଣରେ ଲଜ୍ଜା ରକ୍ଷା କର। 24:31
- ଜାଣ ଯେ ଅଲ୍ଲାହ ସେମାନଙ୍କୁ ସୁରକ୍ଷା ଓ ଶାନ୍ତି ଦିଅନ୍ତି, ଯେଉଁମାନେ ତାଙ୍କ ଉପାସନା କରନ୍ତି ଏବଂ ସତ୍କର୍ମ କରନ୍ତି। 24:55
- ଅନୁମତି ବିନା ପିତାମାତାଙ୍କ ନିଜ କୋଠରୀକୁ ପ୍ରବେଶ କର ନାହିଁ। 24:58
- ନମ୍ର ଓ ବିନମ୍ର ହୁଅ। 25:63
- ମିଥ୍ୟା ସାକ୍ଷ୍ୟ ଓ ପ୍ରତାରଣାରୁ ଦୂରେଇ ରୁହ। 25:72
